import { Schedule } from '../types';

export const exportScheduleToJson = (schedule: Schedule) => {
    try {
        const dataStr = JSON.stringify(schedule, null, 2);
        const blob = new Blob([dataStr], { type: "application/json" });
        const url = URL.createObjectURL(blob);
        const link = document.createElement('a');

        const date = new Date().toISOString().slice(0, 10);
        link.href = url;
        link.download = `bienve_backup_${date}.json`;
        document.body.appendChild(link);
        link.click();

        // Clean up
        setTimeout(() => {
            document.body.removeChild(link);
            window.URL.revokeObjectURL(url);
        }, 0);
    } catch (error) {
        console.error("Error exporting schedule:", error);
        throw new Error("No se pudo exportar la copia de seguridad.");
    }
};

export const parseAndValidateSchedule = (jsonString: string): Schedule => {
    try {
        const parsed = JSON.parse(jsonString);

        // Basic validation: Check if it's an object
        if (typeof parsed !== 'object' || parsed === null) {
            throw new Error("Formato de archivo inválido.");
        }

        // Re-hydrate Date objects
        // We iterate through the structure to convert date strings back to Date objects
        const hydratedSchedule: Schedule = {};

        Object.keys(parsed).forEach(weekId => {
            if (Array.isArray(parsed[weekId])) {
                hydratedSchedule[weekId] = parsed[weekId].map((day: any) => ({
                    ...day,
                    date: new Date(day.date),
                    // Ensure status is valid number or default to Work
                    status: typeof day.status === 'number' ? day.status : 0 
                }));
            }
        });

        return hydratedSchedule;
    } catch (error) {
        console.error("Error parsing schedule file:", error);
        throw new Error("El archivo seleccionado no es válido o está dañado.");
    }
};

import React, { useRef, useState } from 'react';
import { ArrowDownTrayIcon, ArrowUpTrayIcon, ArchiveBoxIcon } from './icons';

interface BackupModalProps {
    onClose: () => void;
    onExport: () => void;
    onImport: (file: File) => void;
    onRestoreAutoBackup: () => void;
    hasAutoBackup: boolean;
}

const BackupModal: React.FC<BackupModalProps> = ({ onClose, onExport, onImport, onRestoreAutoBackup, hasAutoBackup }) => {
    const fileInputRef = useRef<HTMLInputElement>(null);
    const [importError, setImportError] = useState<string>('');

    const handleFileChange = (e: React.ChangeEvent<HTMLInputElement>) => {
        const file = e.target.files?.[0];
        if (file) {
            if (file.type !== "application/json" && !file.name.endsWith('.json')) {
                setImportError("Por favor, selecciona un archivo .json válido.");
                return;
            }
            setImportError('');
            onImport(file);
        }
    };

    return (
        <div className="fixed inset-0 bg-black/70 flex items-center justify-center z-50 p-4 animate-fade-in" onClick={onClose}>
            <div 
                className="bg-gray-800 rounded-2xl shadow-xl w-full max-w-md p-6 sm:p-8 border border-gray-700 animate-fade-in-scale-up"
                onClick={e => e.stopPropagation()}
            >
                <h2 className="text-2xl font-bold text-red-400 text-center mb-2">Copias de Seguridad</h2>
                <p className="text-gray-400 text-center text-sm mb-6">
                    Gestiona tus datos para asegurarte de no perder ningún turno.
                </p>

                <div className="space-y-4">
                    {/* Export Section */}
                    <div className="bg-gray-700/50 p-4 rounded-xl border border-gray-600">
                        <div className="flex items-center space-x-3 mb-2">
                            <ArrowDownTrayIcon className="w-6 h-6 text-green-400" />
                            <h3 className="font-semibold text-gray-200">Exportar Datos</h3>
                        </div>
                        <p className="text-xs text-gray-400 mb-3">Descarga un archivo con todos tus horarios guardados.</p>
                        <button 
                            onClick={onExport}
                            className="w-full py-2 bg-gray-700 hover:bg-gray-600 border border-gray-500 rounded-lg transition text-sm font-medium"
                        >
                            Descargar Copia (.json)
                        </button>
                    </div>

                    {/* Import Section */}
                    <div className="bg-gray-700/50 p-4 rounded-xl border border-gray-600">
                        <div className="flex items-center space-x-3 mb-2">
                            <ArrowUpTrayIcon className="w-6 h-6 text-blue-400" />
                            <h3 className="font-semibold text-gray-200">Importar Datos</h3>
                        </div>
                        <p className="text-xs text-gray-400 mb-3">Restaura tus horarios desde un archivo previamente descargado.</p>
                        <input 
                            type="file" 
                            accept=".json" 
                            ref={fileInputRef} 
                            className="hidden" 
                            onChange={handleFileChange}
                        />
                        <button 
                            onClick={() => fileInputRef.current?.click()}
                            className="w-full py-2 bg-gray-700 hover:bg-gray-600 border border-gray-500 rounded-lg transition text-sm font-medium"
                        >
                            Seleccionar Archivo
                        </button>
                        {importError && <p className="text-red-400 text-xs mt-2">{importError}</p>}
                    </div>

                    {/* Auto Backup Section */}
                    <div className="bg-gray-700/50 p-4 rounded-xl border border-gray-600">
                        <div className="flex items-center space-x-3 mb-2">
                            <ArchiveBoxIcon className="w-6 h-6 text-yellow-400" />
                            <h3 className="font-semibold text-gray-200">Restauración Automática</h3>
                        </div>
                        <p className="text-xs text-gray-400 mb-3">
                            Recupera la copia de seguridad automática generada hoy al abrir la app. Útil si borraste algo por error.
                        </p>
                        <button 
                            onClick={onRestoreAutoBackup}
                            disabled={!hasAutoBackup}
                            className={`w-full py-2 border rounded-lg transition text-sm font-medium ${
                                hasAutoBackup 
                                ? 'bg-gray-700 hover:bg-gray-600 border-gray-500 text-white' 
                                : 'bg-gray-800 border-gray-700 text-gray-500 cursor-not-allowed'
                            }`}
                        >
                            {hasAutoBackup ? 'Restaurar Copia de Hoy' : 'No hay copia disponible hoy'}
                        </button>
                    </div>
                </div>

                <div className="mt-8 text-center">
                    <button onClick={onClose} className="px-6 py-2 bg-gray-600 hover:bg-gray-500 text-white font-semibold rounded-lg transition">
                        Cerrar
                    </button>
                </div>
            </div>
        </div>
    );
};

export default BackupModal;

import React, { useState, useRef, useEffect } from 'react';
import { DownloadIcon, CalendarDownloadIcon, DocumentTextIcon, ArchiveBoxIcon } from './icons';

interface SummaryProps {
    totalHours: number;
    overtimeHours: number;
    onDownload: () => void;
    isDownloading: boolean;
    onDownloadMonth: () => void;
    isDownloadingMonth: boolean;
    onOpenCustomPeriodModal: () => void;
    isDownloadingCustomPeriod: boolean;
    onOpenBackupModal: () => void;
}

const Summary: React.FC<SummaryProps> = ({ 
    totalHours, 
    overtimeHours, 
    onDownload, 
    isDownloading, 
    onDownloadMonth, 
    isDownloadingMonth,
    onOpenCustomPeriodModal,
    isDownloadingCustomPeriod,
    onOpenBackupModal
}) => {
    const [isMenuOpen, setIsMenuOpen] = useState(false);
    const menuRef = useRef<HTMLDivElement>(null);

    useEffect(() => {
        const handleClickOutside = (event: MouseEvent) => {
            if (menuRef.current && !menuRef.current.contains(event.target as Node)) {
                setIsMenuOpen(false);
            }
        };
        document.addEventListener('mousedown', handleClickOutside);
        return () => {
            document.removeEventListener('mousedown', handleClickOutside);
        };
    }, []);

    const isAnyDownloadInProgress = isDownloading || isDownloadingMonth || isDownloadingCustomPeriod;

    return (
        <footer className="sticky bottom-0 bg-gray-800/80 backdrop-blur-sm border-t border-gray-700 p-3 shadow-top">
            <div className="max-w-7xl mx-auto flex justify-between items-center gap-4">
                {/* --- Sección Izquierda: Horas --- */}
                <div className="flex space-x-4 sm:space-x-6 text-center">
                    <div>
                        <p className="text-xs sm:text-sm text-gray-400">Totales</p>
                        <p className="text-xl sm:text-2xl font-bold text-red-400">{totalHours.toFixed(2)}</p>
                    </div>
                    <div>
                        <p className="text-xs sm:text-sm text-gray-400">Extra</p>
                        <p className={`text-xl sm:text-2xl font-bold ${overtimeHours > 0 ? 'text-yellow-400' : 'text-gray-200'}`}>
                            {overtimeHours.toFixed(2)}
                        </p>
                    </div>
                </div>

                {/* --- Sección Derecha: Descarga y Opciones --- */}
                <div className="relative" ref={menuRef}>
                    <button
                        onClick={() => setIsMenuOpen(!isMenuOpen)}
                        disabled={isAnyDownloadInProgress}
                        className="flex items-center space-x-2 px-4 py-2 sm:px-6 sm:py-3 bg-red-600 hover:bg-red-500 text-white font-semibold rounded-lg shadow-md transition-transform transform hover:scale-105 duration-300 disabled:bg-gray-500 disabled:cursor-not-allowed disabled:scale-100"
                    >
                        <DownloadIcon className="w-5 h-5" />
                        <span className="hidden sm:inline">{isAnyDownloadInProgress ? 'Generando...' : 'Opciones'}</span>
                    </button>
                    {isMenuOpen && (
                        <div className="absolute bottom-full mb-2 w-full min-w-max rounded-md shadow-lg bg-gray-700 ring-1 ring-black ring-opacity-5 z-20 animate-fade-in right-0 origin-bottom-right">
                            <div className="py-1">
                                <button
                                    onClick={() => { onDownload(); setIsMenuOpen(false); }}
                                    disabled={isDownloading}
                                    className="w-full flex items-center space-x-3 text-left px-4 py-3 text-sm text-gray-200 hover:bg-gray-600 disabled:text-gray-400 disabled:cursor-not-allowed border-b border-gray-600"
                                >
                                    <DownloadIcon className="w-5 h-5" />
                                    <span>{isDownloading ? 'Generando...' : 'Descargar Semana'}</span>
                                </button>
                                <button
                                    onClick={() => { onDownloadMonth(); setIsMenuOpen(false); }}
                                    disabled={isDownloadingMonth}
                                    className="w-full flex items-center space-x-3 text-left px-4 py-3 text-sm text-gray-200 hover:bg-gray-600 disabled:text-gray-400 disabled:cursor-not-allowed"
                                >
                                    <CalendarDownloadIcon className="w-5 h-5" />
                                    <span>{isDownloadingMonth ? 'Generando...' : 'Descargar Mes'}</span>
                                </button>
                                <button
                                    onClick={() => { onOpenCustomPeriodModal(); setIsMenuOpen(false); }}
                                    disabled={isDownloadingCustomPeriod}
                                    className="w-full flex items-center space-x-3 text-left px-4 py-3 text-sm text-gray-200 hover:bg-gray-600 disabled:text-gray-400 disabled:cursor-not-allowed"
                                >
                                    <DocumentTextIcon className="w-5 h-5" />
                                    <span>{isDownloadingCustomPeriod ? 'Generando...' : 'Periodo Personalizado'}</span>
                                </button>
                                <div className="border-t border-gray-600 my-1"></div>
                                <button
                                    onClick={() => { onOpenBackupModal(); setIsMenuOpen(false); }}
                                    className="w-full flex items-center space-x-3 text-left px-4 py-3 text-sm text-gray-200 hover:bg-gray-600"
                                >
                                    <ArchiveBoxIcon className="w-5 h-5 text-yellow-400" />
                                    <span>Copias de Seguridad</span>
                                </button>
                            </div>
                        </div>
                    )}
                </div>
            </div>
        </footer>
    );
};

export default Summary;

import React, { useState, useMemo, useCallback, useEffect } from 'react';
import { Day, Schedule, DayStatus } from './types';
import { getWeekId, getWeekDays, getWeekTitle, getDaysInMonth } from './utils/dateUtils';
import { calculateHoursFromShift } from './services/scheduleService';
import { downloadScheduleAsPdf, downloadMonthScheduleAsPdf, downloadCustomPeriodPdf } from './services/pdfService';
import Header from './components/Header';
import WeekView from './components/WeekView';
import Summary from './components/Summary';
import EditShiftModal from './components/EditShiftModal';
import { useShiftTemplates } from './hooks/useShiftTemplates';
import CalendarPickerModal from './components/CalendarPickerModal';
import ManageTemplatesModal from './components/ManageTemplatesModal';
import CustomPeriodModal from './components/CustomPeriodModal';
import Login from './components/Login';
import ConfirmModal from './components/ConfirmModal';
import BackupModal from './components/BackupModal';
import { exportScheduleToJson, parseAndValidateSchedule } from './services/dataService';

const SCHEDULE_STORAGE_KEY = 'bienveAppSchedule';
const AUTO_BACKUP_STORAGE_KEY = 'bienveAppSchedule_auto_backup';
const BACKUP_DATE_KEY = 'bienveApp_lastBackupDate';
const AUTH_STORAGE_KEY = 'bienveAppIsAuthenticated';

const App: React.FC = () => {
    const [isAuthenticated, setIsAuthenticated] = useState(() => {
        return localStorage.getItem(AUTH_STORAGE_KEY) === 'true';
    });

    const [currentDate, setCurrentDate] = useState(new Date());
    const [schedule, setSchedule] = useState<Schedule>(() => {
        try {
            const savedSchedule = localStorage.getItem(SCHEDULE_STORAGE_KEY);
            if (savedSchedule) {
                const parsed = JSON.parse(savedSchedule);
                // Re-hydrate Date objects
                Object.keys(parsed).forEach(weekId => {
                    parsed[weekId] = parsed[weekId].map((day: any) => ({
                        ...day,
                        date: new Date(day.date),
                    }));
                });
                return parsed;
            }
        } catch (error) {
            console.error("Failed to load schedule from localStorage", error);
        }
        return {};
    });

    const [editingDay, setEditingDay] = useState<Day | null>(null);
    const { templates, addTemplate, deleteTemplate } = useShiftTemplates();
    const [isManagingTemplates, setIsManagingTemplates] = useState(false);
    const [isDownloading, setIsDownloading] = useState(false);
    const [isDownloadingMonth, setIsDownloadingMonth] = useState(false);
    const [isDownloadingCustomPeriod, setIsDownloadingCustomPeriod] = useState(false);
    const [isCalendarOpen, setIsCalendarOpen] = useState(false);
    const [isCustomPeriodModalOpen, setIsCustomPeriodModalOpen] = useState(false);
    const [isLogoutModalOpen, setIsLogoutModalOpen] = useState(false);
    const [isBackupModalOpen, setIsBackupModalOpen] = useState(false);

    useEffect(() => {
        localStorage.setItem(AUTH_STORAGE_KEY, String(isAuthenticated));
    }, [isAuthenticated]);

    // Save schedule to localStorage whenever it changes
    useEffect(() => {
        try {
            localStorage.setItem(SCHEDULE_STORAGE_KEY, JSON.stringify(schedule));
        } catch (error) {
            console.error("Failed to save schedule to localStorage", error);
        }
    }, [schedule]);

    // Automatic Daily Backup Logic
    useEffect(() => {
        try {
            const today = new Date().toDateString();
            const lastBackupDate = localStorage.getItem(BACKUP_DATE_KEY);
            const savedSchedule = localStorage.getItem(SCHEDULE_STORAGE_KEY);

            // If we have data, and we haven't backed up today yet, save a backup.
            if (savedSchedule && savedSchedule !== '{}' && lastBackupDate !== today) {
                localStorage.setItem(AUTO_BACKUP_STORAGE_KEY, savedSchedule);
                localStorage.setItem(BACKUP_DATE_KEY, today);
                console.log("Automatic daily backup created successfully.");
            }
        } catch (error) {
            console.error("Failed to perform auto-backup", error);
        }
    }, []); // Empty dependency array ensures this runs only once on app mount

    const weekId = useMemo(() => getWeekId(currentDate), [currentDate]);

    const weekDays = useMemo(() => {
        const days = getWeekDays(currentDate);
        if (!schedule[weekId]) {
            return days.map(date => ({ date, shift: '', status: DayStatus.Work }));
        }
        const scheduledDaysMap = new Map(schedule[weekId].map(d => [new Date(d.date).toISOString().slice(0, 10), d]));
        return days.map(date => scheduledDaysMap.get(date.toISOString().slice(0, 10)) || { date, shift: '', status: DayStatus.Work });
    }, [currentDate, schedule, weekId]);

    const handleUpdateDay = useCallback((updatedDay: Day) => {
        setSchedule(prevSchedule => {
            const currentWeekData = prevSchedule[weekId] || weekDays;
            const newWeekDays = [...currentWeekData];
            const dayIndex = newWeekDays.findIndex(d => new Date(d.date).toISOString().slice(0, 10) === updatedDay.date.toISOString().slice(0, 10));
            if (dayIndex !== -1) {
                newWeekDays[dayIndex] = updatedDay;
            } else {
                newWeekDays.push(updatedDay);
            }
            return { ...prevSchedule, [weekId]: newWeekDays };
        });
        setEditingDay(null);
    }, [weekId, weekDays]);

    const { totalHours, overtimeHours } = useMemo(() => {
        const workHours = weekDays.reduce((acc, day) => {
            if (day.status === DayStatus.Work) {
                return acc + calculateHoursFromShift(day.shift);
            }
            return acc;
        }, 0);

        const daysOff = weekDays.filter(d => d.status === DayStatus.Holiday || d.status === DayStatus.Vacation).length;
        const extraDaysOff = Math.max(0, daysOff - 2);
        const weeklyTarget = Math.max(0, 40 - (extraDaysOff * 8));

        const overtime = workHours - weeklyTarget;

        return { totalHours: workHours, overtimeHours: overtime };
    }, [weekDays]);

    const handlePrevWeek = () => {
        const newDate = new Date(currentDate);
        newDate.setDate(newDate.getDate() - 7);
        setCurrentDate(newDate);
    };

    const handleNextWeek = () => {
        const newDate = new Date(currentDate);
        newDate.setDate(newDate.getDate() + 7);
        setCurrentDate(newDate);
    };

    const handleDateSelect = (date: Date) => {
        setCurrentDate(date);
        setIsCalendarOpen(false);
    };

    const handleDownload = async () => {
        setIsDownloading(true);
        try {
            await downloadScheduleAsPdf({
                weekDays,
                currentDate,
                totalHours,
                overtimeHours
            });
        } catch (error) {
            console.error("PDF Download failed:", error);
            alert(error instanceof Error ? error.message : "Ocurrió un error inesperado al generar el PDF.");
        } finally {
            setIsDownloading(false);
        }
    };

    const handleDownloadMonth = async () => {
        setIsDownloadingMonth(true);
        try {
            const daysInMonth = getDaysInMonth(currentDate);

            const scheduleMap = new Map<string, Day>();
            Object.values(schedule).flat().forEach((day: Day) => {
                const dayKey = new Date(day.date).toISOString().slice(0, 10);
                scheduleMap.set(dayKey, day);
            });

            const totalHoursMonth = daysInMonth.reduce((acc, date) => {
                const dayKey = date.toISOString().slice(0, 10);
                const day = scheduleMap.get(dayKey);
                if (day && day.status === DayStatus.Work) {
                    return acc + calculateHoursFromShift(day.shift);
                }
                return acc;
            }, 0);

            let overtimeBalanceMonth = 0.0;
            const processedWeekIds = new Set<string>();

            daysInMonth.forEach(dateInMonth => {
                const weekId = getWeekId(dateInMonth);
                if (processedWeekIds.has(weekId)) {
                    return;
                }

                const fullWeekDays = getWeekDays(dateInMonth);
                const fullWeekDaysWithData = fullWeekDays.map(dateOfWeek => {
                    const dayKey = dateOfWeek.toISOString().slice(0, 10);
                    return scheduleMap.get(dayKey) || { date: dateOfWeek, shift: '', status: DayStatus.Work };
                });

                const isWorkWeek = fullWeekDaysWithData.some(day => day.status === DayStatus.Work);

                if (isWorkWeek) {
                    const workHoursInWeek = fullWeekDaysWithData.reduce((acc, day) => {
                        if (day.status === DayStatus.Work) {
                            return acc + calculateHoursFromShift(day.shift);
                        }
                        return acc;
                    }, 0);

                    const daysOff = fullWeekDaysWithData.filter(d => d.status === DayStatus.Holiday || d.status === DayStatus.Vacation).length;
                    const extraDaysOff = Math.max(0, daysOff - 2);
                    const weeklyTarget = Math.max(0, 40 - (extraDaysOff * 8));

                    overtimeBalanceMonth += (workHoursInWeek - weeklyTarget);
                }

                processedWeekIds.add(weekId);
            });

            const totalOvertimeMonth = overtimeBalanceMonth;

            const monthDaysForPdf = daysInMonth
                .map(date => {
                    const dayKey = date.toISOString().slice(0, 10);
                    return scheduleMap.get(dayKey) || { date, shift: '', status: DayStatus.Work };
                })
                .filter(day => day.shift.trim() !== '' || day.status !== DayStatus.Work);

            await downloadMonthScheduleAsPdf({
                monthDays: monthDaysForPdf,
                currentDate,
                totalHours: totalHoursMonth,
                overtimeHours: totalOvertimeMonth
            });

        } catch (error) {
            console.error("Monthly PDF Download failed:", error);
            alert(error instanceof Error ? error.message : "Ocurrió un error inesperado al generar el PDF del mes.");
        } finally {
            setIsDownloadingMonth(false);
        }
    };

    const handleDownloadCustomPeriod = async (startDate: Date, endDate: Date) => {
        setIsDownloadingCustomPeriod(true);
        setIsCustomPeriodModalOpen(false);

        try {
            const periodDates: Date[] = [];
            let loopDate = new Date(startDate);
            while (loopDate <= endDate) {
                periodDates.push(new Date(loopDate));
                loopDate.setDate(loopDate.getDate() + 1);
            }

            const scheduleMap = new Map<string, Day>();
            Object.values(schedule).flat().forEach((day: Day) => {
                const dayKey = new Date(day.date).toISOString().slice(0, 10);
                scheduleMap.set(dayKey, day);
            });

            const periodDaysWithData = periodDates.map(date => {
                const dayKey = date.toISOString().slice(0, 10);
                return scheduleMap.get(dayKey) || { date, shift: '', status: DayStatus.Work };
            });

            const totalHoursPeriod = periodDaysWithData.reduce((acc, day) => {
                if (day && day.status === DayStatus.Work) {
                    return acc + calculateHoursFromShift(day.shift);
                }
                return acc;
            }, 0);

            const processedWeekIds = new Set<string>();
            let overtimeBalancePeriod = 0.0;

            periodDaysWithData.forEach(dayInPeriod => {
                const weekId = getWeekId(dayInPeriod.date);

                if (!processedWeekIds.has(weekId)) {
                    const fullWeekDays = getWeekDays(dayInPeriod.date);
                    const fullWeekDaysWithData = fullWeekDays.map(dateOfWeek => {
                        const dayKey = dateOfWeek.toISOString().slice(0, 10);
                        return scheduleMap.get(dayKey) || { date: dateOfWeek, shift: '', status: DayStatus.Work };
                    });

                    const isWorkWeek = fullWeekDaysWithData.some(day => day.status === DayStatus.Work);

                    if (isWorkWeek) {
                        const workHoursInWeek = fullWeekDaysWithData.reduce((acc, day) => {
                            if (day.status === DayStatus.Work) {
                                return acc + calculateHoursFromShift(day.shift);
                            }
                            return acc;
                        }, 0);

                        const daysOff = fullWeekDaysWithData.filter(d => d.status === DayStatus.Holiday || d.status === DayStatus.Vacation).length;
                        const extraDaysOff = Math.max(0, daysOff - 2);
                        const weeklyTarget = Math.max(0, 40 - (extraDaysOff * 8));

                        overtimeBalancePeriod += (workHoursInWeek - weeklyTarget);
                    }

                    processedWeekIds.add(weekId);
                }
            });

            const totalOvertimePeriod = overtimeBalancePeriod;

            const periodDaysForPdf = periodDaysWithData.filter(day => day.shift.trim() !== '' || day.status !== DayStatus.Work);

            await downloadCustomPeriodPdf({
                periodDays: periodDaysForPdf,
                startDate,
                endDate,
                totalHours: totalHoursPeriod,
                overtimeHours: totalOvertimePeriod
            });

        } catch (error) {
            console.error("Custom Period PDF Download failed:", error);
            alert(error instanceof Error ? error.message : "Ocurrió un error inesperado al generar el PDF del periodo personalizado.");
        } finally {
            setIsDownloadingCustomPeriod(false);
        }
    };

    const handleLogin = () => {
        setIsAuthenticated(true);
    };

    const handleLogout = () => {
        setIsAuthenticated(false);
        setIsLogoutModalOpen(false);
    };

    // --- Backup & Restore Handlers ---

    const handleExportBackup = () => {
        exportScheduleToJson(schedule);
    };

    const handleImportBackup = async (file: File) => {
        const reader = new FileReader();
        reader.onload = (e) => {
            try {
                const content = e.target?.result as string;
                const newSchedule = parseAndValidateSchedule(content);

                // Merge strategies? For now, we'll replace or merge intelligently?
                // The requirement says "do not delete/modify EXISTING functionality".
                // Importing typically replaces the state. Let's merge to be safe, overwriting only conflicts?
                // Actually, a restore usually implies "Make my app look like this file".
                setSchedule(newSchedule);
                setIsBackupModalOpen(false);
                alert("Copia de seguridad restaurada correctamente.");
            } catch (error) {
                alert(error instanceof Error ? error.message : "Error al importar el archivo.");
            }
        };
        reader.readAsText(file);
    };

    const handleRestoreAutoBackup = () => {
        try {
            const autoBackup = localStorage.getItem(AUTO_BACKUP_STORAGE_KEY);
            if (autoBackup) {
                const newSchedule = parseAndValidateSchedule(autoBackup);
                setSchedule(newSchedule);
                setIsBackupModalOpen(false);
                alert("Copia automática de hoy restaurada.");
            } else {
                alert("No se encontró ninguna copia automática.");
            }
        } catch (error) {
            alert("Error al restaurar la copia automática.");
        }
    };

    const hasAutoBackup = !!localStorage.getItem(AUTO_BACKUP_STORAGE_KEY);

    if (!isAuthenticated) {
        return <Login onLogin={handleLogin} />;
    }

    return (
        <div className="min-h-screen bg-gray-900 text-gray-100 flex flex-col font-sans">
            <Header
                currentWeekTitle={getWeekTitle(currentDate)}
                onPrevWeek={handlePrevWeek}
                onNextWeek={handleNextWeek}
                onCalendarClick={() => setIsCalendarOpen(true)}
                onLogout={() => setIsLogoutModalOpen(true)}
            />
            <main className="flex-grow py-4 md:py-6 lg:py-8">
                <WeekView 
                    days={weekDays} 
                    onEditDay={setEditingDay} 
                />
            </main>
            <Summary 
                totalHours={totalHours} 
                overtimeHours={overtimeHours}
                onDownload={handleDownload}
                isDownloading={isDownloading}
                onDownloadMonth={handleDownloadMonth}
                isDownloadingMonth={isDownloadingMonth}
                onOpenCustomPeriodModal={() => setIsCustomPeriodModalOpen(true)}
                isDownloadingCustomPeriod={isDownloadingCustomPeriod}
                onOpenBackupModal={() => setIsBackupModalOpen(true)}
            />
            {editingDay && (
                <EditShiftModal
                    day={editingDay}
                    onClose={() => setEditingDay(null)}
                    onSave={handleUpdateDay}
                    templates={templates}
                    onManageTemplates={() => setIsManagingTemplates(true)}
                />
            )}
            {isManagingTemplates && (
                <ManageTemplatesModal
                    templates={templates}
                    onAddTemplate={addTemplate}
                    onDeleteTemplate={deleteTemplate}
                    onClose={() => setIsManagingTemplates(false)}
                />
            )}
             {isCalendarOpen && (
                <CalendarPickerModal
                    isOpen={isCalendarOpen}
                    onClose={() => setIsCalendarOpen(false)}
                    currentDate={currentDate}
                    onDateSelect={handleDateSelect}
                />
            )}
            {isCustomPeriodModalOpen && (
                <CustomPeriodModal
                    isOpen={isCustomPeriodModalOpen}
                    onClose={() => setIsCustomPeriodModalOpen(false)}
                    onConfirm={handleDownloadCustomPeriod}
                />
            )}
            {isLogoutModalOpen && (
                <ConfirmModal
                    isOpen={isLogoutModalOpen}
                    title="Cerrar Sesión"
                    message="¿Estás seguro de que quieres cerrar la sesión?"
                    onConfirm={handleLogout}
                    onCancel={() => setIsLogoutModalOpen(false)}
                    confirmText="Cerrar Sesión"
                />
            )}
            {isBackupModalOpen && (
                <BackupModal
                    onClose={() => setIsBackupModalOpen(false)}
                    onExport={handleExportBackup}
                    onImport={handleImportBackup}
                    onRestoreAutoBackup={handleRestoreAutoBackup}
                    hasAutoBackup={hasAutoBackup}
                />
            )}
        </div>
    );
};

export default App;

import React from 'react';
import { LogoIcon, ChevronLeftIcon, ChevronRightIcon, CalendarIcon, LogoutIcon } from './icons';
import DriveSync from './DriveSync';
import { DriveUser } from '../types';

interface HeaderProps {
    currentWeekTitle: string;
    onPrevWeek: () => void;
    onNextWeek: () => void;
