let app: FirebaseApp | null = null;
let auth: Auth | null = null;
let db: Firestore | null = null;

export const initFirebase = (config: FirebaseConfig) => {
    if (app) return; // Already initialized
    try {
        app = initializeApp(config);
        auth = getAuth(app);
        db = getFirestore(app);
        console.log("Firebase initialized successfully");
    } catch (error) {
        console.error("Error initializing Firebase:", error);
        throw error;
    }
};

export const loginWithGoogle = async () => {
    if (!auth) throw new Error("Firebase not initialized");
    const provider = new GoogleAuthProvider();
    try {
        await signInWithPopup(auth, provider);
    } catch (error) {
        console.error("Error signing in with Google:", error);
        throw error;
    }
};

export const logoutUser = async () => {
    if (!auth) return;
    try {
        await signOut(auth);
    } catch (error) {
        console.error("Error signing out:", error);
    }
};

export const subscribeToAuthChanges = (callback: (user: User | null) => void) => {
    if (!auth) return () => {};
    return onAuthStateChanged(auth, callback);
};

// Firestore Logic

export const saveScheduleToFirestore = async (userId: string, schedule: Schedule) => {
    if (!db) return;
    try {
        // We store the schedule as a JSON string to avoid deep nesting issues or 
        // unnecessary complexity with dates in Firestore, though parsing dates is needed on load.
        // However, standard objects are fine. We will store dates as ISO strings automatically by JSON.stringify behavior
        // passing through the API, but Firestore handles Dates. 
        // Ideally, we clean the schedule object to ensure it saves cleanly.

        // Let's perform a deep copy to ensure we aren't mutating the state
        // and handle Date conversion if necessary. Firestore supports Date objects.

        await setDoc(doc(db, "users", userId), {
            schedule: JSON.stringify(schedule),
            lastUpdated: new Date()
        }, { merge: true });

    } catch (error) {
        console.error("Error saving schedule to Firestore:", error);
        throw error;
    }
};

export const subscribeToSchedule = (userId: string, onUpdate: (schedule: Schedule) => void) => {
    if (!db) return () => {};

    const userDocRef = doc(db, "users", userId);

    const unsubscribe = onSnapshot(userDocRef, (docSnapshot) => {
        if (docSnapshot.exists()) {
            const data = docSnapshot.data();
            if (data && data.schedule) {
                try {
                    const parsedSchedule = JSON.parse(data.schedule);
                    // Re-hydrate dates
                    Object.keys(parsedSchedule).forEach(weekId => {
                        parsedSchedule[weekId] = parsedSchedule[weekId].map((day: any) => ({
                            ...day,
                            date: new Date(day.date),
                        }));
                    });
                    onUpdate(parsedSchedule);
                } catch (e) {
                    console.error("Error parsing schedule from Firestore:", e);
                }
            }
        }
    });

    return unsubscribe;
};

