const SCHEDULE_STORAGE_KEY = 'bienveAppSchedule';
const AUTH_STORAGE_KEY = 'bienveAppIsAuthenticated';

// --- TEST DATA FOR DECEMBER 2025 ---
const TEST_DATA_DEC_2025 = {
  "2025-49": [
    {"date": "2025-12-01", "shift": "", "status": 1},
