const App: React.FC = () => {
    // --- Authentication State (App Local) ---
    const [isAuthenticated, setIsAuthenticated] = useState(() => {
        return localStorage.getItem(AUTH_STORAGE_KEY) === 'true';
    });

    // --- Core Data State ---
    const [currentDate, setCurrentDate] = useState(new Date());
    const [schedule, setSchedule] = useState<Schedule>(() => {
        try {
            const savedSchedule = localStorage.getItem(SCHEDULE_STORAGE_KEY);
            if (savedSchedule) {
                const parsed = JSON.parse(savedSchedule);
                Object.keys(parsed).forEach(weekId => {
                    parsed[weekId] = parsed[weekId].map((day: any) => ({
                        ...day,
                        date: new Date(day.date),
                    }));
                });
                return parsed;
            }
        } catch (error) {
            console.error("Failed to load schedule from localStorage", error);
        }
        return {};
    });

    // --- Firebase Integration State ---
    const [firebaseUser, setFirebaseUser] = useState<FirebaseUser | null>(null);
    const [isFirebaseConfigModalOpen, setIsFirebaseConfigModalOpen] = useState(false);
    const [isSyncing, setIsSyncing] = useState(false);
    const isRemoteUpdate = useRef(false); // Flag to prevent infinite loops (Local -> Cloud -> Local -> Cloud)

    // --- UI State ---
    const [editingDay, setEditingDay] = useState<Day | null>(null);
    const { templates, addTemplate, deleteTemplate } = useShiftTemplates();
    const [isManagingTemplates, setIsManagingTemplates] = useState(false);
    const [isDownloading, setIsDownloading] = useState(false);
    const [isDownloadingMonth, setIsDownloadingMonth] = useState(false);
    const [isDownloadingCustomPeriod, setIsDownloadingCustomPeriod] = useState(false);
    const [isCalendarOpen, setIsCalendarOpen] = useState(false);
    const [isCustomPeriodModalOpen, setIsCustomPeriodModalOpen] = useState(false);
    const [isBackupModalOpen, setIsBackupModalOpen] = useState(false);
    const [isLogoutModalOpen, setIsLogoutModalOpen] = useState(false);

    // Persist Local Login
    useEffect(() => {
        localStorage.setItem(AUTH_STORAGE_KEY, String(isAuthenticated));
    }, [isAuthenticated]);

    // Persist Local Schedule
    useEffect(() => {
        try {
            localStorage.setItem(SCHEDULE_STORAGE_KEY, JSON.stringify(schedule));
        } catch (error) {
            console.error("Failed to save schedule to localStorage", error);
        }
    }, [schedule]);

    // --- Firebase Logic ---

    // 1. Initialize Firebase on load if config exists
    useEffect(() => {
        if (isAuthenticated && isFirebaseConfigured()) {
            const config = getFirebaseConfig();
            if (config) {
                try {
                    initFirebase(config);
                    // Subscribe to auth state changes
                    const unsubscribeAuth = subscribeToAuthChanges((user) => {
                        if (user) {
                            setFirebaseUser({
                                uid: user.uid,
                                displayName: user.displayName,
                                email: user.email,
                                photoURL: user.photoURL
                            });
                        } else {
                            setFirebaseUser(null);
                        }
                    });
                    return () => unsubscribeAuth();
                } catch (e) {
                    console.error("Firebase init failed", e);
                }
            }
        }
    }, [isAuthenticated]);

    // 2. Real-time Listener for Schedule (Cloud -> Local)
    useEffect(() => {
        if (firebaseUser?.uid) {
            setIsSyncing(true);
            const unsubscribeSchedule = subscribeToSchedule(firebaseUser.uid, (remoteSchedule) => {
                console.log("Remote schedule update received");
                isRemoteUpdate.current = true; // Set flag
                setSchedule(remoteSchedule); // Update local state
                setIsSyncing(false);

                // Reset flag after a tick to allow local edits to resume triggering saves
                setTimeout(() => {
                    isRemoteUpdate.current = false;
                }, 100);
            });
            return () => unsubscribeSchedule();
        }
    }, [firebaseUser?.uid]);

    // 3. Save to Firestore (Local -> Cloud)
    const debouncedSaveToFirestore = useDebouncedCallback(async (currentSchedule: Schedule, uid: string) => {
        if (!uid) return;
        setIsSyncing(true);
        try {
            await saveScheduleToFirestore(uid, currentSchedule);
        } catch (e) {
            console.error("Save to firestore failed", e);
        } finally {
            setIsSyncing(false);
        }
    }, 1000);

    useEffect(() => {
        // Only save if logged in AND it wasn't a remote update just now
        if (firebaseUser?.uid && !isRemoteUpdate.current) {
            debouncedSaveToFirestore(schedule, firebaseUser.uid);
        }
    }, [schedule, firebaseUser, debouncedSaveToFirestore]);


    // --- Handlers ---

    const handleFirebaseLogin = async () => {
        if (!isFirebaseConfigured()) {
            setIsFirebaseConfigModalOpen(true);
            return;
        }
        try {
            const config = getFirebaseConfig();
            if (config) initFirebase(config);
            await loginWithGoogle();
        } catch (error: any) {
            alert(error.message);
        }
    };

    const handleFirebaseLogout = async () => {
        await logoutUser();
        setFirebaseUser(null);
    };

    const handleTestConnection = async () => {
        if (!firebaseUser?.uid) return;
        setIsSyncing(true);
        try {
            await testFirestoreConnection(firebaseUser.uid);
            alert("✅ Conexión exitosa: Tus datos se guardan en la nube correctamente.");
        } catch (error: any) {
            console.error(error);
            alert(`❌ Error de conexión: ${error.message || 'No se pudo contactar con Firestore.'}`);
        } finally {
            setIsSyncing(false);
        }
    };

    const handleConfigSave = (config: FirebaseConfig) => {
        saveFirebaseConfig(config);
        setIsFirebaseConfigModalOpen(false);
        // Attempt init immediately
        try {
            initFirebase(config);
            // Trigger login flow immediately after config if desired, or let user click Connect again
            handleFirebaseLogin(); 
        } catch (e) {
            alert("Error inicializando Firebase con esa configuración.");
        }
    };

    // --- Backup & Data Handlers ---

    const handleExport = () => {
        exportScheduleToJson(schedule);
    };

    const handleImport = (file: File) => {
        const reader = new FileReader();
        reader.onload = (e) => {
            const text = e.target?.result as string;
            try {
                const newSchedule = parseAndValidateSchedule(text);
                if (window.confirm("¿Estás seguro? Esto reemplazará tu horario actual con el del archivo.")) {
                    setSchedule(newSchedule);
                    setIsBackupModalOpen(false);
                    alert("Horario importado correctamente.");
                }
            } catch (err) {
                alert("Error al importar el archivo: Formato inválido.");
            }
        };
        reader.readAsText(file);
    };

    const handleLoadTestData = () => {
        if (window.confirm("Esto reemplazará tus datos actuales con los datos de prueba de Diciembre 2025. ¿Continuar?")) {
            const loadedSchedule: Schedule = {};

            // Re-hydrate dates from the constant
            Object.keys(TEST_DATA_DEC_2025).forEach(weekId => {
                loadedSchedule[weekId] = (TEST_DATA_DEC_2025 as any)[weekId].map((day: any) => ({
                    ...day,
                    date: new Date(day.date),
                    status: day.status
                }));
            });

            setSchedule(loadedSchedule);
            // Navigate to start of December 2025 safely (Local time)
            // Use numeric constructor (Year, MonthIndex, Day) to avoid UTC offsets shifting the day
            setCurrentDate(new Date(2025, 11, 1)); 
            setIsBackupModalOpen(false);
            // No alert needed if the UI updates immediately
        }
    };

    const handleRestoreAutoBackup = () => {
        // En un futuro podríamos guardar un 'backup' en otra key de localStorage al iniciar la app.
        alert("Función de restauración automática no disponible en este momento.");
    };

    // --- Date & Schedule Logic (Existing) ---

    const weekId = useMemo(() => getWeekId(currentDate), [currentDate]);

    const weekDays = useMemo(() => {
        const days = getWeekDays(currentDate);
        if (!schedule[weekId]) {
            return days.map(date => ({ date, shift: '', status: DayStatus.Work }));
        }
        const scheduledDaysMap = new Map(schedule[weekId].map(d => [new Date(d.date).toISOString().slice(0, 10), d]));
        return days.map(date => scheduledDaysMap.get(date.toISOString().slice(0, 10)) || { date, shift: '', status: DayStatus.Work });
    }, [currentDate, schedule, weekId]);

    const handleUpdateDay = useCallback((updatedDay: Day) => {
        setSchedule(prevSchedule => {
            const currentWeekData = prevSchedule[weekId] || weekDays;
            const newWeekDays = [...currentWeekData];
            const dayIndex = newWeekDays.findIndex(d => new Date(d.date).toISOString().slice(0, 10) === updatedDay.date.toISOString().slice(0, 10));
            if (dayIndex !== -1) {
                newWeekDays[dayIndex] = updatedDay;
            } else {
                newWeekDays.push(updatedDay);
            }
            return { ...prevSchedule, [weekId]: newWeekDays };
        });
        setEditingDay(null);
    }, [weekId, weekDays]);

    const { totalHours, overtimeHours } = useMemo(() => {
        const workHours = weekDays.reduce((acc, day) => {
            if (day.status === DayStatus.Work) {
                return acc + calculateHoursFromShift(day.shift);
            }
            return acc;
        }, 0);

        const daysOff = weekDays.filter(d => d.status === DayStatus.Holiday || d.status === DayStatus.Vacation).length;
        const extraDaysOff = Math.max(0, daysOff - 2);
        const weeklyTarget = Math.max(0, 40 - (extraDaysOff * 8));

        const overtime = workHours - weeklyTarget;

        return { totalHours: workHours, overtimeHours: overtime };
    }, [weekDays]);

    const handlePrevWeek = () => {
        const newDate = new Date(currentDate);
        newDate.setDate(newDate.getDate() - 7);
        setCurrentDate(newDate);
    };

    const handleNextWeek = () => {
        const newDate = new Date(currentDate);
        newDate.setDate(newDate.getDate() + 7);
        setCurrentDate(newDate);
    };

    const handleDateSelect = (date: Date) => {
        setCurrentDate(date);
        setIsCalendarOpen(false);
    };

    // --- Report Downloads ---

    const handleDownload = async () => {
        setIsDownloading(true);
        try {
            await downloadScheduleAsPdf({ weekDays, currentDate, totalHours, overtimeHours });
        } catch (error) {
            console.error("PDF Error:", error);
            alert("Error al generar PDF.");
        } finally { setIsDownloading(false); }
    };

    const handleDownloadMonth = async () => {
        setIsDownloadingMonth(true);
        try {
            const daysInMonth = getDaysInMonth(currentDate);
             const scheduleMap = new Map<string, Day>();
            Object.values(schedule).flat().forEach((day: Day) => {
                const dayKey = new Date(day.date).toISOString().slice(0, 10);
                scheduleMap.set(dayKey, day);
            });

            const totalHoursMonth = daysInMonth.reduce((acc, date) => {
                const dayKey = date.toISOString().slice(0, 10);
                const day = scheduleMap.get(dayKey);
                if (day && day.status === DayStatus.Work) return acc + calculateHoursFromShift(day.shift);
                return acc;
            }, 0);

            let overtimeBalanceMonth = 0.0;
            const processedWeekIds = new Set<string>();
            daysInMonth.forEach(dateInMonth => {
                 const weekId = getWeekId(dateInMonth);
                if (processedWeekIds.has(weekId)) return;

                const fullWeekDays = getWeekDays(dateInMonth);
                const fullWeekDaysWithData = fullWeekDays.map(dateOfWeek => {
                    const dayKey = dateOfWeek.toISOString().slice(0, 10);
                    return scheduleMap.get(dayKey) || { date: dateOfWeek, shift: '', status: DayStatus.Work };
                });

                const isWorkWeek = fullWeekDaysWithData.some(day => day.status === DayStatus.Work);
                if (isWorkWeek) {
                    const workHoursInWeek = fullWeekDaysWithData.reduce((acc, day) => 
                        day.status === DayStatus.Work ? acc + calculateHoursFromShift(day.shift) : acc, 0);
                    const daysOff = fullWeekDaysWithData.filter(d => d.status === DayStatus.Holiday || d.status === DayStatus.Vacation).length;
                    const weeklyTarget = Math.max(0, 40 - (Math.max(0, daysOff - 2) * 8));
                    overtimeBalanceMonth += (workHoursInWeek - weeklyTarget);
                }
                processedWeekIds.add(weekId);
            });

            const monthDaysForPdf = daysInMonth.map(date => {
                const dayKey = date.toISOString().slice(0, 10);
                return scheduleMap.get(dayKey) || { date, shift: '', status: DayStatus.Work };
            }).filter(day => day.shift.trim() !== '' || day.status !== DayStatus.Work);

            await downloadMonthScheduleAsPdf({ monthDays: monthDaysForPdf, currentDate, totalHours: totalHoursMonth, overtimeHours: overtimeBalanceMonth });
        } catch (error) {
            console.error("Month PDF Error:", error);
            alert("Error al generar PDF mensual.");
        } finally { setIsDownloadingMonth(false); }
    };

    const handleDownloadCustomPeriod = async (startDate: Date, endDate: Date) => {
        setIsDownloadingCustomPeriod(true);
        setIsCustomPeriodModalOpen(false);
        try {
             const periodDates: Date[] = [];
            let loopDate = new Date(startDate);
            while (loopDate <= endDate) {
                periodDates.push(new Date(loopDate));
                loopDate.setDate(loopDate.getDate() + 1);
            }

            const scheduleMap = new Map<string, Day>();
            Object.values(schedule).flat().forEach((day: Day) => {
                const dayKey = new Date(day.date).toISOString().slice(0, 10);
                scheduleMap.set(dayKey, day);
            });

            const periodDaysWithData = periodDates.map(date => {
                const dayKey = date.toISOString().slice(0, 10);
                return scheduleMap.get(dayKey) || { date, shift: '', status: DayStatus.Work };
            });

            const totalHoursPeriod = periodDaysWithData.reduce((acc, day) => 
                 (day && day.status === DayStatus.Work) ? acc + calculateHoursFromShift(day.shift) : acc, 0);

             let overtimeBalancePeriod = 0.0;
            const processedWeekIds = new Set<string>();
            periodDaysWithData.forEach(dayInPeriod => {
                const weekId = getWeekId(dayInPeriod.date);
                if (!processedWeekIds.has(weekId)) {
                    const fullWeekDays = getWeekDays(dayInPeriod.date);
                    const fullWeekDaysWithData = fullWeekDays.map(dateOfWeek => {
                        const dayKey = dateOfWeek.toISOString().slice(0, 10);
                        return scheduleMap.get(dayKey) || { date: dateOfWeek, shift: '', status: DayStatus.Work };
                    });
                     const isWorkWeek = fullWeekDaysWithData.some(day => day.status === DayStatus.Work);
                    if (isWorkWeek) {
                        const workHoursInWeek = fullWeekDaysWithData.reduce((acc, day) => 
                             day.status === DayStatus.Work ? acc + calculateHoursFromShift(day.shift) : acc, 0);
                        const daysOff = fullWeekDaysWithData.filter(d => d.status === DayStatus.Holiday || d.status === DayStatus.Vacation).length;
                        const weeklyTarget = Math.max(0, 40 - (Math.max(0, daysOff - 2) * 8));
                        overtimeBalancePeriod += (workHoursInWeek - weeklyTarget);
                    }
                    processedWeekIds.add(weekId);
                }
            });

            const periodDaysForPdf = periodDaysWithData.filter(day => day.shift.trim() !== '' || day.status !== DayStatus.Work);
            await downloadCustomPeriodPdf({ periodDays: periodDaysForPdf, startDate, endDate, totalHours: totalHoursPeriod, overtimeHours: overtimeBalancePeriod });
        } catch (error) {
            console.error("Custom PDF Error:", error);
            alert("Error al generar reporte personalizado.");
        } finally { setIsDownloadingCustomPeriod(false); }
    };

    const handleLogin = () => { setIsAuthenticated(true); };
    const handleLogout = () => { 
        setIsAuthenticated(false); 
        setIsLogoutModalOpen(false); 
        logoutUser(); // Disconnect firebase
    };

    const hasScheduleData = useMemo(() => Object.keys(schedule).length > 0, [schedule]);

    if (!isAuthenticated) {
        return <Login onLogin={handleLogin} />;
    }

    return (
        <div className="min-h-screen bg-gray-900 text-gray-100 flex flex-col font-sans">
            <Header
                currentWeekTitle={getWeekTitle(currentDate)}
                onPrevWeek={handlePrevWeek}
                onNextWeek={handleNextWeek}
                onCalendarClick={() => setIsCalendarOpen(true)}
                onLogout={() => setIsLogoutModalOpen(true)}
                // Firebase Props
                user={firebaseUser}
                isSyncing={isSyncing}
                onLogin={handleFirebaseLogin}
                onSignOut={handleFirebaseLogout}
                onConfigure={() => setIsFirebaseConfigModalOpen(true)}
                onTestConnection={handleTestConnection}
            />

            <main className="flex-grow py-4 md:py-6 lg:py-8">
                {!hasScheduleData && (
                    <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 mb-8 animate-fade-in-scale-up">
                        <div className="bg-gray-800 border border-red-900/50 rounded-2xl p-6 sm:p-8 flex flex-col md:flex-row items-center justify-between gap-6 shadow-2xl relative overflow-hidden group">
                            <div className="absolute top-0 left-0 w-full h-1 bg-gradient-to-r from-red-600 to-red-800"></div>
                            {/* Decorative background glow */}
                            <div className="absolute -bottom-10 -right-10 w-40 h-40 bg-red-600/10 rounded-full blur-3xl group-hover:bg-red-600/20 transition duration-500"></div>

                            <div className="flex-1 text-center md:text-left z-10">
                                <h2 className="text-2xl sm:text-3xl font-bold text-white mb-2 flex items-center justify-center md:justify-start gap-2">
                                    <span>👋</span>
                                    <span className="bg-clip-text text-transparent bg-gradient-to-r from-white to-gray-400">¡Bienvenido a Bienve App!</span>
                                </h2>
                                <p className="text-gray-400 text-lg leading-relaxed">
                                    Tu agenda está vacía. Para ver el potencial de la app, carga el horario de <strong>Diciembre 2025</strong> con un solo clic.
                                </p>
                            </div>

                            <button 
                                onClick={handleLoadTestData}
                                className="z-10 flex-shrink-0 px-8 py-4 bg-gradient-to-r from-red-600 to-red-700 hover:from-red-500 hover:to-red-600 text-white font-bold rounded-xl shadow-lg shadow-red-900/30 transition-all transform hover:scale-105 active:scale-95 flex items-center gap-3 border border-red-500/30"
                            >
                                <span className="text-xl">🚀</span>
                                <span>Cargar Datos Demo</span>
                            </button>
                        </div>
                    </div>
                )}

                <WeekView 
                    days={weekDays} 
                    onEditDay={setEditingDay} 
                />
            </main>

            <Summary 
                totalHours={totalHours} 
                overtimeHours={overtimeHours}
                onDownload={handleDownload}
                isDownloading={isDownloading}
                onDownloadMonth={handleDownloadMonth}
                isDownloadingMonth={isDownloadingMonth}
                onOpenCustomPeriodModal={() => setIsCustomPeriodModalOpen(true)}
                isDownloadingCustomPeriod={isDownloadingCustomPeriod}
                onOpenBackupModal={() => setIsBackupModalOpen(true)}
            />

            {/* Modals */}
            {editingDay && (
                <EditShiftModal
                    day={editingDay}
                    onClose={() => setEditingDay(null)}
                    onSave={handleUpdateDay}
                    templates={templates}
                    onManageTemplates={() => setIsManagingTemplates(true)}
                />
            )}
            {isManagingTemplates && (
                <ManageTemplatesModal
                    templates={templates}
                    onAddTemplate={addTemplate}
                    onDeleteTemplate={deleteTemplate}
                    onClose={() => setIsManagingTemplates(false)}
                />
            )}
             {isCalendarOpen && (
                <CalendarPickerModal
                    isOpen={isCalendarOpen}
                    onClose={() => setIsCalendarOpen(false)}
                    currentDate={currentDate}
                    onDateSelect={handleDateSelect}
                />
            )}
            {isCustomPeriodModalOpen && (
                <CustomPeriodModal
                    isOpen={isCustomPeriodModalOpen}
                    onClose={() => setIsCustomPeriodModalOpen(false)}
                    onConfirm={handleDownloadCustomPeriod}
                />
            )}
            {isBackupModalOpen && (
                <BackupModal
                    onClose={() => setIsBackupModalOpen(false)}
                    onExport={handleExport}
                    onImport={handleImport}
                    onRestoreAutoBackup={handleRestoreAutoBackup}
                    hasAutoBackup={false} // Feature not implemented yet
                    onLoadTestData={handleLoadTestData}
                />
            )}
            {isLogoutModalOpen && (
                <ConfirmModal
                    isOpen={isLogoutModalOpen}
                    title="Cerrar Sesión"
                    message="¿Estás seguro de que quieres cerrar la sesión de la aplicación?"
                    onConfirm={handleLogout}
                    onCancel={() => setIsLogoutModalOpen(false)}
                    confirmText="Cerrar Sesión"
                />
            )}
            {isFirebaseConfigModalOpen && (
                <FirebaseConfigModal onSave={handleConfigSave} />
            )}
        </div>
    );
};

export default App;

import React, { useState, useMemo, useCallback, useEffect, useRef } from 'react';
import { Day, Schedule, DayStatus, FirebaseUser, FirebaseConfig } from './types';
import { getWeekId, getWeekDays, getWeekTitle, getDaysInMonth } from './utils/dateUtils';
import { calculateHoursFromShift } from './services/scheduleService';
import { downloadScheduleAsPdf, downloadMonthScheduleAsPdf, downloadCustomPeriodPdf } from './services/pdfService';
import { exportScheduleToJson, parseAndValidateSchedule } from './services/dataService';
import Header from './components/Header';
import WeekView from './components/WeekView';
import Summary from './components/Summary';
import EditShiftModal from './components/EditShiftModal';
import { useShiftTemplates } from './hooks/useShiftTemplates';
import CalendarPickerModal from './components/CalendarPickerModal';
import ManageTemplatesModal from './components/ManageTemplatesModal';
import CustomPeriodModal from './components/CustomPeriodModal';
import BackupModal from './components/BackupModal';
import Login from './components/Login';
import ConfirmModal from './components/ConfirmModal';
import FirebaseConfigModal from './components/FirebaseConfigModal';

import { saveFirebaseConfig, getFirebaseConfig, isFirebaseConfigured } from './services/apiKeyService';
import { initFirebase, loginWithGoogle, logoutUser, subscribeToAuthChanges, subscribeToSchedule, saveScheduleToFirestore, testFirestoreConnection } from './services/firebaseService';
import { useDebouncedCallback } from './hooks/useDebouncedCallback';

const SCHEDULE_STORAGE_KEY = 'bienveAppSchedule';
const AUTH_STORAGE_KEY = 'bienveAppIsAuthenticated';

// --- RAW TEST DATA (Flat Array for robust loading) ---
const RAW_TEST_DATA = [
    { date: "2025-12-01", shift: "", status: 1 },
    { date: "2025-12-02", shift: "", status: 1 },
    { date: "2025-12-03", shift: "12-16:30 20-23", status: 0 },
    { date: "2025-12-04", shift: "12-16 20-00", status: 0 },
    { date: "2025-12-05", shift: "19:30 00:30", status: 0 },
    { date: "2025-12-06", shift: "13:30 17:30 20-00", status: 0 },
    { date: "2025-12-07", shift: "13:30 17:30 20-00", status: 0 },
    { date: "2025-12-08", shift: "13:30 17:30 20-23:30", status: 0 },
    { date: "2025-12-09", shift: "12-17 20-00", status: 0 },
    { date: "2025-12-10", shift: "", status: 2 },
    { date: "2025-12-11", shift: "", status: 2 },
    { date: "2025-12-12", shift: "", status: 2 },
    { date: "2025-12-13", shift: "", status: 2 },
    { date: "2025-12-14", shift: "", status: 2 },
    { date: "2025-12-15", shift: "12-17 20-00", status: 0 },
    { date: "2025-12-16", shift: "12-17 20-00", status: 0 },
    { date: "2025-12-17", shift: "12-17", status: 0 },
    { date: "2025-12-18", shift: "", status: 1 },
    { date: "2025-12-19", shift: "12-17 20-", status: 0 },
    { date: "2025-12-20", shift: "12-17 20-00", status: 0 },
    { date: "2025-12-21", shift: "12-17 20-", status: 0 },
    { date: "2025-12-22", shift: "12-16:30 20-00", status: 0 },
    { date: "2025-12-23", shift: "12-17 20-23:30", status: 0 },
    { date: "2025-12-24", shift: "12-17", status: 0 },
    { date: "2025-12-25", shift: "", status: 1 },
    { date: "2025-12-26", shift: "12-17 20-2", status: 0 },
    { date: "2025-12-27", shift: "12-17:30 20-1", status: 0 },
    { date: "2025-12-28", shift: "12-17 20-1", status: 0 }
];

const App: React.FC = () => {
    // --- Authentication State (App Local) ---
    const [isAuthenticated, setIsAuthenticated] = useState(() => {
        return localStorage.getItem(AUTH_STORAGE_KEY) === 'true';
    });

    // --- Core Data State ---
    const [currentDate, setCurrentDate] = useState(new Date());
    const [schedule, setSchedule] = useState<Schedule>(() => {
        try {
            const savedSchedule = localStorage.getItem(SCHEDULE_STORAGE_KEY);
            if (savedSchedule) {
                const parsed = JSON.parse(savedSchedule);
                Object.keys(parsed).forEach(weekId => {
                    parsed[weekId] = parsed[weekId].map((day: any) => ({
                        ...day,
                        date: new Date(day.date),
                    }));
                });
                return parsed;
            }
        } catch (error) {
            console.error("Failed to load schedule from localStorage", error);
        }
        return {};
    });

    // --- Firebase Integration State ---
    const [firebaseUser, setFirebaseUser] = useState<FirebaseUser | null>(null);
    const [isFirebaseConfigModalOpen, setIsFirebaseConfigModalOpen] = useState(false);
    const [isSyncing, setIsSyncing] = useState(false);
    const isRemoteUpdate = useRef(false);

    // --- UI State ---
    const [editingDay, setEditingDay] = useState<Day | null>(null);
    const { templates, addTemplate, deleteTemplate } = useShiftTemplates();
    const [isManagingTemplates, setIsManagingTemplates] = useState(false);
    const [isDownloading, setIsDownloading] = useState(false);
    const [isDownloadingMonth, setIsDownloadingMonth] = useState(false);
    const [isDownloadingCustomPeriod, setIsDownloadingCustomPeriod] = useState(false);
    const [isCalendarOpen, setIsCalendarOpen] = useState(false);
    const [isCustomPeriodModalOpen, setIsCustomPeriodModalOpen] = useState(false);
    const [isBackupModalOpen, setIsBackupModalOpen] = useState(false);
    const [isLogoutModalOpen, setIsLogoutModalOpen] = useState(false);

    useEffect(() => {
        localStorage.setItem(AUTH_STORAGE_KEY, String(isAuthenticated));
    }, [isAuthenticated]);

    useEffect(() => {
        try {
            localStorage.setItem(SCHEDULE_STORAGE_KEY, JSON.stringify(schedule));
        } catch (error) {
            console.error("Failed to save schedule to localStorage", error);
        }
    }, [schedule]);

    // --- Firebase Logic ---
    useEffect(() => {
        if (isAuthenticated && isFirebaseConfigured()) {
            const config = getFirebaseConfig();
            if (config) {
                try {
                    initFirebase(config);
                    const unsubscribeAuth = subscribeToAuthChanges((user) => {
                        if (user) {
                            setFirebaseUser({
                                uid: user.uid,
                                displayName: user.displayName,
                                email: user.email,
                                photoURL: user.photoURL
                            });
                        } else {
                            setFirebaseUser(null);
                        }
                    });
                    return () => unsubscribeAuth();
                } catch (e) {
                    console.error("Firebase init failed", e);
                }
            }
        }
    }, [isAuthenticated]);

    useEffect(() => {
        if (firebaseUser?.uid) {
            setIsSyncing(true);
            const unsubscribeSchedule = subscribeToSchedule(firebaseUser.uid, (remoteSchedule) => {
                isRemoteUpdate.current = true;
                setSchedule(remoteSchedule);
                setIsSyncing(false);
                setTimeout(() => { isRemoteUpdate.current = false; }, 100);
            });
            return () => unsubscribeSchedule();
        }
    }, [firebaseUser?.uid]);

    const debouncedSaveToFirestore = useDebouncedCallback(async (currentSchedule: Schedule, uid: string) => {
        if (!uid) return;
        setIsSyncing(true);
        try {
            await saveScheduleToFirestore(uid, currentSchedule);
        } catch (e) {
            console.error("Save to firestore failed", e);
        } finally {
            setIsSyncing(false);
        }
    }, 1000);

    useEffect(() => {
        if (firebaseUser?.uid && !isRemoteUpdate.current) {
            debouncedSaveToFirestore(schedule, firebaseUser.uid);
        }
    }, [schedule, firebaseUser, debouncedSaveToFirestore]);

    // --- Handlers ---

    const handleFirebaseLogin = async () => {
        if (!isFirebaseConfigured()) {
            setIsFirebaseConfigModalOpen(true);
            return;
        }
        try {
            const config = getFirebaseConfig();
            if (config) initFirebase(config);
            await loginWithGoogle();
        } catch (error: any) {
            alert(error.message);
        }
    };

    const handleFirebaseLogout = async () => {
        await logoutUser();
        setFirebaseUser(null);
    };

    const handleTestConnection = async () => {
        if (!firebaseUser?.uid) return;
        setIsSyncing(true);
        try {
            await testFirestoreConnection(firebaseUser.uid);
            alert("✅ Conexión exitosa: Tus datos se guardan en la nube correctamente.");
        } catch (error: any) {
            alert(`❌ Error de conexión: ${error.message || 'No se pudo contactar con Firestore.'}`);
        } finally {
            setIsSyncing(false);
        }
    };

    const handleConfigSave = (config: FirebaseConfig) => {
        saveFirebaseConfig(config);
        setIsFirebaseConfigModalOpen(false);
        try {
            initFirebase(config);
            handleFirebaseLogin(); 
        } catch (e) {
            alert("Error inicializando Firebase con esa configuración.");
        }
    };

    // --- Backup & Data Handlers ---

    const handleExport = () => exportScheduleToJson(schedule);

    const handleImport = (file: File) => {
        const reader = new FileReader();
        reader.onload = (e) => {
            const text = e.target?.result as string;
            try {
                const newSchedule = parseAndValidateSchedule(text);
                if (window.confirm("¿Estás seguro? Esto reemplazará tu horario actual.")) {
                    setSchedule(newSchedule);
                    setIsBackupModalOpen(false);
                    alert("Horario importado correctamente.");
                }
            } catch (err) {
                alert("Error al importar el archivo.");
            }
        };
        reader.readAsText(file);
    };

    const handleLoadTestData = () => {
        if (window.confirm("Se borrarán tus datos actuales y se cargarán los de prueba (Diciembre 2025). ¿Continuar?")) {
            const newSchedule: Schedule = {};

            // Dynamic Generation: Iterate raw data and calculate weekId on the fly using the app's current logic
            RAW_TEST_DATA.forEach(item => {
                const dateObj = new Date(item.date);
                // Force midday to avoid timezone shifts when calculating week ID
                dateObj.setHours(12, 0, 0, 0); 

                const wId = getWeekId(dateObj);

                if (!newSchedule[wId]) {
                    newSchedule[wId] = [];
                }

                // We need to ensure we don't duplicate days if raw data has multiple days in same week
                // (The raw data is flat, so we just push)
                // But wait, the schedule object expects 7 days per week usually for the UI to be fully populated?
                // The WeekView handles missing days by filling them in, so we just need to save the specific ones.
                // Actually, existing logic often saves fully hydrated weeks. 
                // Let's rely on WeekView to hydrate missing days, but for best results, we just push the data we have.
                // However, the `schedule` state structure in App.tsx typically stores an array of Day objects.
                // Let's just push this specific day.

                newSchedule[wId].push({
                    date: dateObj,
                    shift: item.shift,
                    status: item.status
                });
            });

            setSchedule(newSchedule);

            // Navigation: Set date to Dec 1st, 2025
            const targetDate = new Date(2025, 11, 1, 12, 0, 0);
            setCurrentDate(targetDate);

            setIsBackupModalOpen(false);
        }
    };

    const handleResetData = () => {
        if (window.confirm("PELIGRO: Esto borrará TODOS tus datos guardados en el dispositivo. ¿Estás seguro?")) {
            setSchedule({});
            setCurrentDate(new Date());
            setIsBackupModalOpen(false);
        }
    };

    const handleRestoreAutoBackup = () => {
        alert("Función de restauración automática no disponible en este momento.");
    };

    // --- Date & Schedule Logic ---

    const weekId = useMemo(() => getWeekId(currentDate), [currentDate]);

    const weekDays = useMemo(() => {
        const days = getWeekDays(currentDate);
        if (!schedule[weekId]) {
            return days.map(date => ({ date, shift: '', status: DayStatus.Work }));
        }
        // Merge stored days with the full week structure
        // We need to match by date string YYYY-MM-DD
        const scheduledDaysMap = new Map();
        schedule[weekId].forEach(d => {
             // Handle both string dates (from JSON) and Date objects
             const dDate = new Date(d.date);
             const key = dDate.toISOString().slice(0, 10);
             scheduledDaysMap.set(key, d);
        });

        return days.map(date => {
            const key = date.toISOString().slice(0, 10);
            const found = scheduledDaysMap.get(key);
            if (found) {
                // Ensure we return a properly formatted Day object
                return { 
                    ...found, 
                    date: date // Use the calculated date to ensure time consistency
                };
            }
            return { date, shift: '', status: DayStatus.Work };
        });
    }, [currentDate, schedule, weekId]);

    const handleUpdateDay = useCallback((updatedDay: Day) => {
        setSchedule(prevSchedule => {
            const currentWeekData = prevSchedule[weekId] || weekDays;
            // We need to ensure we work with a clean array of the full week to update one day
            // But `currentWeekData` might be partial if coming from `schedule`. 
            // `weekDays` (from useMemo above) is always full 7 days.

            // Let's use `weekDays` as the base because it represents the *current view*, 
            // which merges stored data + empty placeholders.
            const newWeekDays = weekDays.map(d => {
                if (d.date.toISOString().slice(0, 10) === updatedDay.date.toISOString().slice(0, 10)) {
                    return updatedDay;
                }
                return d;
            });

            return { ...prevSchedule, [weekId]: newWeekDays };
        });
        setEditingDay(null);
    }, [weekId, weekDays]);

    const { totalHours, overtimeHours } = useMemo(() => {
        const workHours = weekDays.reduce((acc, day) => {
            if (day.status === DayStatus.Work) {
                return acc + calculateHoursFromShift(day.shift);
            }
            return acc;
        }, 0);

        const daysOff = weekDays.filter(d => d.status === DayStatus.Holiday || d.status === DayStatus.Vacation).length;
        const extraDaysOff = Math.max(0, daysOff - 2);
        const weeklyTarget = Math.max(0, 40 - (extraDaysOff * 8));
        const overtime = workHours - weeklyTarget;
        return { totalHours: workHours, overtimeHours: overtime };
    }, [weekDays]);

    const handlePrevWeek = () => {
        const newDate = new Date(currentDate);
        newDate.setDate(newDate.getDate() - 7);
        setCurrentDate(newDate);
    };

    const handleNextWeek = () => {
        const newDate = new Date(currentDate);
        newDate.setDate(newDate.getDate() + 7);
        setCurrentDate(newDate);
    };

    const handleDateSelect = (date: Date) => {
        setCurrentDate(date);
        setIsCalendarOpen(false);
    };

    // --- Report Downloads (Unchanged logic abbreviated for clarity) ---
    const handleDownload = async () => {
        setIsDownloading(true);
        try { await downloadScheduleAsPdf({ weekDays, currentDate, totalHours, overtimeHours }); } 
        catch (e) { console.error(e); alert("Error al generar PDF."); } 
        finally { setIsDownloading(false); }
    };

    const handleDownloadMonth = async () => {
        setIsDownloadingMonth(true);
        try {
            const daysInMonth = getDaysInMonth(currentDate);
            // ... (rest of logic same as before, essentially flattening schedule)
             const scheduleMap = new Map<string, Day>();
            Object.values(schedule).flat().forEach((day: Day) => {
                const dayKey = new Date(day.date).toISOString().slice(0, 10);
                scheduleMap.set(dayKey, day);
            });
            // Re-calc logic...
             const totalHoursMonth = daysInMonth.reduce((acc, date) => {
                const dayKey = date.toISOString().slice(0, 10);
                const day = scheduleMap.get(dayKey);
                if (day && day.status === DayStatus.Work) return acc + calculateHoursFromShift(day.shift);
                return acc;
            }, 0);

            // Simplified overtime calculation for monthly pdf (placeholder logic from previous)
            let overtimeBalanceMonth = 0.0; // Recalculated correctly in full implementation
            // ... (keeping existing complex logic implicitly or explicitly)
             const processedWeekIds = new Set<string>();
            daysInMonth.forEach(dateInMonth => {
                 const weekId = getWeekId(dateInMonth);
                if (processedWeekIds.has(weekId)) return;
                const fullWeekDays = getWeekDays(dateInMonth);
                const fullWeekDaysWithData = fullWeekDays.map(dateOfWeek => {
                    const dayKey = dateOfWeek.toISOString().slice(0, 10);
                    return scheduleMap.get(dayKey) || { date: dateOfWeek, shift: '', status: DayStatus.Work };
                });
                const isWorkWeek = fullWeekDaysWithData.some(day => day.status === DayStatus.Work);
                if (isWorkWeek) {
                    const workHoursInWeek = fullWeekDaysWithData.reduce((acc, day) => 
                        day.status === DayStatus.Work ? acc + calculateHoursFromShift(day.shift) : acc, 0);
                    const daysOff = fullWeekDaysWithData.filter(d => d.status === DayStatus.Holiday || d.status === DayStatus.Vacation).length;
                    const weeklyTarget = Math.max(0, 40 - (Math.max(0, daysOff - 2) * 8));
                    overtimeBalanceMonth += (workHoursInWeek - weeklyTarget);
                }
                processedWeekIds.add(weekId);
            });

            const monthDaysForPdf = daysInMonth.map(date => {
                const dayKey = date.toISOString().slice(0, 10);
                return scheduleMap.get(dayKey) || { date, shift: '', status: DayStatus.Work };
            }).filter(day => day.shift.trim() !== '' || day.status !== DayStatus.Work);

            await downloadMonthScheduleAsPdf({ monthDays: monthDaysForPdf, currentDate, totalHours: totalHoursMonth, overtimeHours: overtimeBalanceMonth });

        } catch (e) { console.error(e); alert("Error PDF Mensual"); } 
        finally { setIsDownloadingMonth(false); }
    };

    const handleDownloadCustomPeriod = async (startDate: Date, endDate: Date) => {
        setIsDownloadingCustomPeriod(true);
        setIsCustomPeriodModalOpen(false);
        try {
            // ... (Same logic as existing App.tsx for custom period)
            const periodDates: Date[] = [];
            let loopDate = new Date(startDate);
            while (loopDate <= endDate) {
                periodDates.push(new Date(loopDate));
                loopDate.setDate(loopDate.getDate() + 1);
            }
            const scheduleMap = new Map<string, Day>();
            Object.values(schedule).flat().forEach((day: Day) => {
                const dayKey = new Date(day.date).toISOString().slice(0, 10);
                scheduleMap.set(dayKey, day);
            });
            const periodDaysWithData = periodDates.map(date => {
                const dayKey = date.toISOString().slice(0, 10);
                return scheduleMap.get(dayKey) || { date, shift: '', status: DayStatus.Work };
            });
            const totalHoursPeriod = periodDaysWithData.reduce((acc, day) => 
                 (day && day.status === DayStatus.Work) ? acc + calculateHoursFromShift(day.shift) : acc, 0);
             let overtimeBalancePeriod = 0.0;
            const processedWeekIds = new Set<string>();
            periodDaysWithData.forEach(dayInPeriod => {
                const weekId = getWeekId(dayInPeriod.date);
                if (!processedWeekIds.has(weekId)) {
                    const fullWeekDays = getWeekDays(dayInPeriod.date);
                    const fullWeekDaysWithData = fullWeekDays.map(dateOfWeek => {
                        const dayKey = dateOfWeek.toISOString().slice(0, 10);
                        return scheduleMap.get(dayKey) || { date: dateOfWeek, shift: '', status: DayStatus.Work };
                    });
                     const isWorkWeek = fullWeekDaysWithData.some(day => day.status === DayStatus.Work);
                    if (isWorkWeek) {
                        const workHoursInWeek = fullWeekDaysWithData.reduce((acc, day) => 
                             day.status === DayStatus.Work ? acc + calculateHoursFromShift(day.shift) : acc, 0);
                        const daysOff = fullWeekDaysWithData.filter(d => d.status === DayStatus.Holiday || d.status === DayStatus.Vacation).length;
                        const weeklyTarget = Math.max(0, 40 - (Math.max(0, daysOff - 2) * 8));
                        overtimeBalancePeriod += (workHoursInWeek - weeklyTarget);
                    }
                    processedWeekIds.add(weekId);
                }
            });
            const periodDaysForPdf = periodDaysWithData.filter(day => day.shift.trim() !== '' || day.status !== DayStatus.Work);
            await downloadCustomPeriodPdf({ periodDays: periodDaysForPdf, startDate, endDate, totalHours: totalHoursPeriod, overtimeHours: overtimeBalancePeriod });
        } catch (e) { console.error(e); alert("Error PDF Personalizado"); }
        finally { setIsDownloadingCustomPeriod(false); }
    };

    const handleLogin = () => { setIsAuthenticated(true); };
    const handleLogout = () => { 
        setIsAuthenticated(false); 
        setIsLogoutModalOpen(false); 
        logoutUser(); 
    };

    // Improved detection: Check if there is ANY actual work or status change recorded
    const hasScheduleData = useMemo(() => {
        return Object.values(schedule).some(week => 
            Array.isArray(week) && week.some(day => day.shift.trim() !== '' || day.status !== DayStatus.Work)
        );
    }, [schedule]);

    if (!isAuthenticated) {
        return <Login onLogin={handleLogin} />;
    }

    return (
        <div className="min-h-screen bg-gray-900 text-gray-100 flex flex-col font-sans">
            <Header
                currentWeekTitle={getWeekTitle(currentDate)}
                onPrevWeek={handlePrevWeek}
                onNextWeek={handleNextWeek}
                onCalendarClick={() => setIsCalendarOpen(true)}
                onLogout={() => setIsLogoutModalOpen(true)}
                user={firebaseUser}
                isSyncing={isSyncing}
                onLogin={handleFirebaseLogin}
                onSignOut={handleFirebaseLogout}
                onConfigure={() => setIsFirebaseConfigModalOpen(true)}
                onTestConnection={handleTestConnection}
            />

            <main className="flex-grow py-4 md:py-6 lg:py-8">
                {!hasScheduleData && (
                    <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 mb-8 animate-fade-in-scale-up">
                        <div className="bg-gray-800 border border-red-900/50 rounded-2xl p-6 sm:p-8 flex flex-col md:flex-row items-center justify-between gap-6 shadow-2xl relative overflow-hidden group">
                            <div className="absolute top-0 left-0 w-full h-1 bg-gradient-to-r from-red-600 to-red-800"></div>
                            <div className="absolute -bottom-10 -right-10 w-40 h-40 bg-red-600/10 rounded-full blur-3xl group-hover:bg-red-600/20 transition duration-500"></div>

                            <div className="flex-1 text-center md:text-left z-10">
                                <h2 className="text-2xl sm:text-3xl font-bold text-white mb-2 flex items-center justify-center md:justify-start gap-2">
                                    <span>👋</span>
                                    <span className="bg-clip-text text-transparent bg-gradient-to-r from-white to-gray-400">¡Bienvenido a Bienve App!</span>
                                </h2>
                                <p className="text-gray-400 text-lg leading-relaxed">
                                    Tu agenda está vacía. Carga el horario de <strong>Diciembre 2025</strong> para ver cómo funciona.
                                </p>
                            </div>

                            <button 
                                onClick={handleLoadTestData}
                                className="z-10 flex-shrink-0 px-8 py-4 bg-gradient-to-r from-red-600 to-red-700 hover:from-red-500 hover:to-red-600 text-white font-bold rounded-xl shadow-lg shadow-red-900/30 transition-all transform hover:scale-105 active:scale-95 flex items-center gap-3 border border-red-500/30"
                            >
                                <span className="text-xl">🚀</span>
                                <span>Cargar Datos Demo</span>
                            </button>
                        </div>
                    </div>
                )}

                <WeekView 
                    days={weekDays} 
                    onEditDay={setEditingDay} 
                />
            </main>

            <Summary 
                totalHours={totalHours} 
                overtimeHours={overtimeHours}
                onDownload={handleDownload}
                isDownloading={isDownloading}
                onDownloadMonth={handleDownloadMonth}
                isDownloadingMonth={isDownloadingMonth}
                onOpenCustomPeriodModal={() => setIsCustomPeriodModalOpen(true)}
                isDownloadingCustomPeriod={isDownloadingCustomPeriod}
                onOpenBackupModal={() => setIsBackupModalOpen(true)}
            />

            {editingDay && (
                <EditShiftModal
                    day={editingDay}
                    onClose={() => setEditingDay(null)}
                    onSave={handleUpdateDay}
                    templates={templates}
                    onManageTemplates={() => setIsManagingTemplates(true)}
                />
            )}
            {isManagingTemplates && (
                <ManageTemplatesModal
                    templates={templates}
                    onAddTemplate={addTemplate}
                    onDeleteTemplate={deleteTemplate}
                    onClose={() => setIsManagingTemplates(false)}
                />
            )}
             {isCalendarOpen && (
                <CalendarPickerModal
                    isOpen={isCalendarOpen}
                    onClose={() => setIsCalendarOpen(false)}
                    currentDate={currentDate}
                    onDateSelect={handleDateSelect}
                />
            )}
            {isCustomPeriodModalOpen && (
                <CustomPeriodModal
                    isOpen={isCustomPeriodModalOpen}
                    onClose={() => setIsCustomPeriodModalOpen(false)}
                    onConfirm={handleDownloadCustomPeriod}
                />
            )}
            {isBackupModalOpen && (
                <BackupModal
                    onClose={() => setIsBackupModalOpen(false)}
                    onExport={handleExport}
                    onImport={handleImport}
                    onRestoreAutoBackup={handleRestoreAutoBackup}
                    hasAutoBackup={false}
                    onLoadTestData={handleLoadTestData}
                    onResetData={handleResetData}
                />
            )}
            {isLogoutModalOpen && (
                <ConfirmModal
                    isOpen={isLogoutModalOpen}
                    title="Cerrar Sesión"
                    message="¿Estás seguro de que quieres cerrar la sesión de la aplicación?"
                    onConfirm={handleLogout}
                    onCancel={() => setIsLogoutModalOpen(false)}
                    confirmText="Cerrar Sesión"
                />
            )}
            {isFirebaseConfigModalOpen && (
                <FirebaseConfigModal onSave={handleConfigSave} />
            )}
        </div>
    );
};

export default App;

import React, { useRef, useState } from 'react';
import { ArrowDownTrayIcon, ArrowUpTrayIcon, ArchiveBoxIcon, SparklesIcon, TrashIcon } from './icons';

interface BackupModalProps {
    onClose: () => void;
    onExport: () => void;
    onImport: (file: File) => void;
    onRestoreAutoBackup: () => void;
    hasAutoBackup: boolean;
    onLoadTestData: () => void;
    onResetData?: () => void;
}

const BackupModal: React.FC<BackupModalProps> = ({ onClose, onExport, onImport, onRestoreAutoBackup, hasAutoBackup, onLoadTestData, onResetData }) => {
    const fileInputRef = useRef<HTMLInputElement>(null);
    const [importError, setImportError] = useState<string>('');

    const handleFileChange = (e: React.ChangeEvent<HTMLInputElement>) => {
        const file = e.target.files?.[0];
