export interface ShiftPart {
    start: number; // hour as a float, e.g., 12.5 for 12:30
    end: number;
}

/**
 * Parses a time string (e.g., "12:30", "16.5", "16.30", "C", "1") into a decimal hour value.
 */
const parseTimeToHours = (timeStr: string): number => {
    if (!timeStr || typeof timeStr !== 'string') return NaN;

    // Normalize: replace commas with dots, trim, uppercase
    const trimmedStr = timeStr.trim().toUpperCase().replace(/,/g, '.');

    if (trimmedStr === '') return NaN;
    if (trimmedStr === 'C' || trimmedStr === 'CIERRE') return 24; // Treat Cierre as 24:00 (midnight) or 00:00 next day conceptually

    // Safety check: a time token shouldn't contain a range separator here
    if (trimmedStr.includes('-')) return NaN;

    // 1. Handle HH:MM format explicitly (Standard)
    if (trimmedStr.includes(':')) {
        const parts = trimmedStr.split(':');
        if (parts.length >= 2) {
            const hours = Number(parts[0]);
            const minutes = Number(parts[1]);

            if (!isNaN(hours) && !isNaN(minutes)) {
                // Validate logical ranges
                if (hours < 0 || hours > 24 || minutes < 0 || minutes >= 60) return NaN;
                if (hours === 24 && minutes > 0) return NaN; 
                return hours + (minutes / 60);
            }
        }
        return NaN;
    }

    // 2. Handle Decimal format (e.g. 17.5 OR 17.30 meaning 17:30)
    if (trimmedStr.includes('.')) {
        const parts = trimmedStr.split('.');
        if (parts.length === 2) {
            const hours = Number(parts[0]);
            const fractionalStr = parts[1];

            // Critical Fix: Ambiguity between 17.5 (17:30) and 17.50 (17:50).
            if (fractionalStr.length === 2) {
                const minutes = Number(fractionalStr);
                if (!isNaN(hours) && !isNaN(minutes) && minutes < 60) {
                     return hours + (minutes / 60);
                }
            }
            return Number(trimmedStr);
        }
    }

    // 3. Handle Integer hours (e.g. "20", "1", "00")
    const num = Number(trimmedStr);
    if (!isNaN(num) && num >= 0 && num <= 24) {
        return num;
    }

    return NaN;
};

// Helper to handle shift duration logic consistently
const createShiftPart = (start: number, end: number): ShiftPart => {
    let endTime = end;

    // Logic for crossing midnight:
    // If End < Start (e.g. 20 to 1), add 24 to End.
    if (endTime < start) {
        endTime += 24;
    }
    // Explicitly handle 00 as 24 if it is the end time and start is not 0
    else if (endTime === 0 && start > 0) {
        endTime = 24;
    }

    return { start, end: endTime };
};

/**
 * Parses a shift string into parts.
 * Restored to standard parsing logic.
 */
export const parseShiftParts = (shift: string): ShiftPart[] => {
    if (!shift || typeof shift !== 'string') return [];

    // Pre-process: 
    let normalizedShift = shift
        .replace(/[–—]/g, '-') 
        .replace(/\s*-\s*/g, '-')
        .trim();

    if (!normalizedShift) return [];

    const parts: ShiftPart[] = [];
    const tokens = normalizedShift.split(/\s+/);

    for (let i = 0; i < tokens.length; i++) {
        const token = tokens[i];

        if (token.includes('-')) {
            const subTokens = token.split('-');

            for (let j = 0; j < subTokens.length - 1; j += 2) {
                const startStr = subTokens[j];
                const endStr = subTokens[j+1]; 

                if (startStr && endStr) {
                    const start = parseTimeToHours(startStr);
                    const end = parseTimeToHours(endStr);

                    if (!isNaN(start) && !isNaN(end)) {
                        parts.push(createShiftPart(start, end));
                    }
                }
            }
        }
    }

    return parts;
};

export const calculateHoursFromShift = (shift: string): number => {
    const parts = parseShiftParts(shift);
    const rawTotal = parts.reduce((total, part) => total + (part.end - part.start), 0);
    return Math.round(rawTotal * 100) / 100;
};

// --- New Formatter Function for PDF ---
export const formatTime = (decimalTime: number): string => {
    let hours = Math.floor(decimalTime);
    const minutes = Math.round((decimalTime - hours) * 60);

    // Handle crossing midnight for display (e.g. 25h -> 01:00)
    if (hours >= 24) hours -= 24;

    const hStr = hours.toString().padStart(2, '0');
    const mStr = minutes.toString().padStart(2, '0');
    return `${hStr}:${mStr}`;
};

export const formatShift = (shift: string): string => {
    const parts = parseShiftParts(shift);
    if (parts.length === 0) return shift;

    return parts.map(part => {
        return `${formatTime(part.start)}-${formatTime(part.end)}`;
    }).join(' ');
};

// Helper to get the week number for a date (Local Time implementation)
const getWeekNumber = (d: Date): number => {
    // Copy date so don't modify original
    d = new Date(d.getFullYear(), d.getMonth(), d.getDate());
    // Set to nearest Thursday: current date + 4 - current day number
    // Make Sunday's day number 7
    d.setDate(d.getDate() + 4 - (d.getDay() || 7));
    // Get first day of year
    const yearStart = new Date(d.getFullYear(), 0, 1);
    // Calculate full weeks to nearest Thursday
    const weekNo = Math.ceil((((d.getTime() - yearStart.getTime()) / 86400000) + 1) / 7);
    return weekNo;
}

export const getWeekId = (date: Date): string => {
    const year = date.getFullYear();
    const week = getWeekNumber(date);
    return `${year}-${week.toString().padStart(2, '0')}`;
};

export const getWeekDays = (date: Date): Date[] => {
    const days: Date[] = [];
    const current = new Date(date);

    // Get Monday of the current week
    const day = current.getDay();
    const diff = current.getDate() - day + (day === 0 ? -6 : 1); // adjust when day is sunday

    const monday = new Date(current.setDate(diff));
    monday.setHours(0, 0, 0, 0); // Normalize time

    for (let i = 0; i < 7; i++) {
        const nextDay = new Date(monday);
        nextDay.setDate(monday.getDate() + i);
        days.push(nextDay);
    }
    return days;
};

export const getDaysInMonth = (date: Date): Date[] => {
    const year = date.getFullYear();
    const month = date.getMonth();
    const days: Date[] = [];
    const day = new Date(year, month, 1);

    while (day.getMonth() === month) {
        days.push(new Date(day));
        day.setDate(day.getDate() + 1);
    }
    return days;
};

export const getWeekTitle = (date: Date): string => {
    const weekDays = getWeekDays(date);
    const firstDay = weekDays[0];
    const lastDay = weekDays[6];

    const options: Intl.DateTimeFormatOptions = { month: 'long', day: 'numeric' };

    const firstDayStr = firstDay.toLocaleDateString('es-ES', options);
    const lastDayStr = lastDay.toLocaleDateString('es-ES', options);

    return `Semana del ${firstDayStr} al ${lastDayStr}`;
};

export const getMonthTitle = (date: Date): string => {
    return date.toLocaleDateString('es-ES', { month: 'long', year: 'numeric' });
};

export const formatDayDate = (date: Date): string => {
    return date.toLocaleDateString('es-ES', { day: 'numeric' });
};

export const formatDayName = (date: Date): string => {
    return date.toLocaleDateString('es-ES', { weekday: 'long' });
};

export interface ShiftPart {
    start: number;
    end: number;
}

const parseTimeToHours = (timeStr: string): number => {
    if (!timeStr) return NaN;
    const trimmed = timeStr.trim().toUpperCase().replace(/,/g, '.');

    if (trimmed === 'C' || trimmed === 'CIERRE') return 24;

    // Handle HH:MM
    if (trimmed.includes(':')) {
        const [h, m] = trimmed.split(':').map(Number);
        if (!isNaN(h) && !isNaN(m)) return h + m / 60;
    }

    // Handle Decimal
    const num = Number(trimmed);
    if (!isNaN(num)) {
        // Simple heuristic: if it's 17.30, treat as 17.5 for calculation? 
        // Or assume user uses decimal hours directly (17.5 = 17:30).
        // Let's stick to standard decimal hours for simplicity as strictly requested.
        return num;
    }

    return NaN;
};

export const parseShiftParts = (shift: string): ShiftPart[] => {
    if (!shift) return [];

    // Normalize format: "12-16 20-23"
    const normalized = shift.replace(/\s*-\s*/g, '-').trim();
    const parts: ShiftPart[] = [];

    const tokens = normalized.split(' ');

    tokens.forEach(token => {
        if (token.includes('-')) {
            const [startStr, endStr] = token.split('-');
            if (startStr && endStr) {
                const start = parseTimeToHours(startStr);
                let end = parseTimeToHours(endStr);

                if (!isNaN(start) && !isNaN(end)) {
                    // Handle midnight crossing (20-02 -> 20 to 26)
                    if (end < start) end += 24;
                    // Handle 00 as 24
                    if (end === 0 && start > 0) end = 24;

                    parts.push({ start, end });
                }
            }
        }
    });

    return parts;
};

export const calculateHoursFromShift = (shift: string): number => {
    const parts = parseShiftParts(shift);
    const total = parts.reduce((acc, part) => acc + (part.end - part.start), 0);
    return Math.round(total * 100) / 100;
};

// Formatter for PDF output
const formatTimeVal = (val: number) => {
    let h = Math.floor(val);
    const m = Math.round((val - h) * 60);
    if (h >= 24) h -= 24;
    return `${h.toString().padStart(2,'0')}:${m.toString().padStart(2,'0')}`;
};

export const formatShift = (shift: string): string => {
    const parts = parseShiftParts(shift);
    if (parts.length === 0) return shift; // Return original if not parseable
    return parts.map(p => `${formatTimeVal(p.start)}-${formatTimeVal(p.end)}`).join(' ');
};

import React, { useState, useMemo, useCallback, useEffect, useRef } from 'react';
import { Day, Schedule, DayStatus, FirebaseUser, FirebaseConfig } from './types';
import { getWeekId, getWeekDays, getWeekTitle, getDaysInMonth } from './utils/dateUtils';
import { calculateHoursFromShift } from './services/scheduleService';
import { downloadScheduleAsPdf, downloadMonthScheduleAsPdf, downloadCustomPeriodPdf } from './services/pdfService';
import Header from './components/Header';
import WeekView from './components/WeekView';
import Summary from './components/Summary';
import EditShiftModal from './components/EditShiftModal';
import { useShiftTemplates } from './hooks/useShiftTemplates';
import CalendarPickerModal from './components/CalendarPickerModal';
import ManageTemplatesModal from './components/ManageTemplatesModal';
import CustomPeriodModal from './components/CustomPeriodModal';
import Login from './components/Login';
import ConfirmModal from './components/ConfirmModal';
import FirebaseConfigModal from './components/FirebaseConfigModal';

import { saveFirebaseConfig, getFirebaseConfig, isFirebaseConfigured } from './services/apiKeyService';
import { initFirebase, loginWithGoogle, logoutUser, subscribeToAuthChanges, subscribeToSchedule, saveScheduleToFirestore, testFirestoreConnection } from './services/firebaseService';
import { useDebouncedCallback } from './hooks/useDebouncedCallback';

const SCHEDULE_STORAGE_KEY = 'bienveAppSchedule';
const AUTH_STORAGE_KEY = 'bienveAppIsAuthenticated';

const App: React.FC = () => {
    // --- Authentication State (App Local) ---
    const [isAuthenticated, setIsAuthenticated] = useState(() => {
        return localStorage.getItem(AUTH_STORAGE_KEY) === 'true';
    });

    // --- Core Data State ---
    const [currentDate, setCurrentDate] = useState(new Date());
    const [schedule, setSchedule] = useState<Schedule>(() => {
        try {
            const savedSchedule = localStorage.getItem(SCHEDULE_STORAGE_KEY);
            if (savedSchedule) {
                const parsed = JSON.parse(savedSchedule);
                Object.keys(parsed).forEach(weekId => {
                    parsed[weekId] = parsed[weekId].map((day: any) => ({
                        ...day,
                        date: new Date(day.date),
                    }));
                });
                return parsed;
            }
        } catch (error) {
            console.error("Failed to load schedule from localStorage", error);
        }
        return {};
    });

    // --- Firebase Integration State ---
    const [firebaseUser, setFirebaseUser] = useState<FirebaseUser | null>(null);
    const [isFirebaseConfigModalOpen, setIsFirebaseConfigModalOpen] = useState(false);
    const [isSyncing, setIsSyncing] = useState(false);
    const isRemoteUpdate = useRef(false);

    // --- UI State ---
    const [editingDay, setEditingDay] = useState<Day | null>(null);
    const { templates, addTemplate, deleteTemplate } = useShiftTemplates();
    const [isManagingTemplates, setIsManagingTemplates] = useState(false);
    const [isDownloading, setIsDownloading] = useState(false);
    const [isDownloadingMonth, setIsDownloadingMonth] = useState(false);
    const [isDownloadingCustomPeriod, setIsDownloadingCustomPeriod] = useState(false);
    const [isCalendarOpen, setIsCalendarOpen] = useState(false);
    const [isCustomPeriodModalOpen, setIsCustomPeriodModalOpen] = useState(false);
    const [isLogoutModalOpen, setIsLogoutModalOpen] = useState(false);

    useEffect(() => {
        localStorage.setItem(AUTH_STORAGE_KEY, String(isAuthenticated));
    }, [isAuthenticated]);

    useEffect(() => {
        try {
            localStorage.setItem(SCHEDULE_STORAGE_KEY, JSON.stringify(schedule));
        } catch (error) {
            console.error("Failed to save schedule to localStorage", error);
        }
    }, [schedule]);

    // --- Firebase Logic ---
    useEffect(() => {
        if (isAuthenticated && isFirebaseConfigured()) {
            const config = getFirebaseConfig();
            if (config) {
                try {
                    initFirebase(config);
                    const unsubscribeAuth = subscribeToAuthChanges((user) => {
                        if (user) {
                            setFirebaseUser({
                                uid: user.uid,
                                displayName: user.displayName,
                                email: user.email,
                                photoURL: user.photoURL
                            });
                        } else {
                            setFirebaseUser(null);
                        }
                    });
                    return () => unsubscribeAuth();
                } catch (e) {
                    console.error("Firebase init failed", e);
                }
            }
        }
    }, [isAuthenticated]);

    useEffect(() => {
        if (firebaseUser?.uid) {
            setIsSyncing(true);
            const unsubscribeSchedule = subscribeToSchedule(firebaseUser.uid, (remoteSchedule) => {
                isRemoteUpdate.current = true;
                setSchedule(remoteSchedule);
                setIsSyncing(false);
                setTimeout(() => { isRemoteUpdate.current = false; }, 100);
            });
            return () => unsubscribeSchedule();
        }
    }, [firebaseUser?.uid]);

    const debouncedSaveToFirestore = useDebouncedCallback(async (currentSchedule: Schedule, uid: string) => {
        if (!uid) return;
        setIsSyncing(true);
        try {
            await saveScheduleToFirestore(uid, currentSchedule);
        } catch (e) {
            console.error("Save to firestore failed", e);
        } finally {
            setIsSyncing(false);
        }
    }, 1000);

    useEffect(() => {
        if (firebaseUser?.uid && !isRemoteUpdate.current) {
            debouncedSaveToFirestore(schedule, firebaseUser.uid);
        }
    }, [schedule, firebaseUser, debouncedSaveToFirestore]);

    // --- Handlers ---

    const handleFirebaseLogin = async () => {
        if (!isFirebaseConfigured()) {
            setIsFirebaseConfigModalOpen(true);
            return;
        }
        try {
            const config = getFirebaseConfig();
            if (config) initFirebase(config);
            await loginWithGoogle();
        } catch (error: any) {
            alert(error.message);
        }
    };

    const handleFirebaseLogout = async () => {
        await logoutUser();
        setFirebaseUser(null);
    };

    const handleTestConnection = async () => {
        if (!firebaseUser?.uid) return;
        setIsSyncing(true);
        try {
            await testFirestoreConnection(firebaseUser.uid);
            alert("✅ Conexión exitosa: Tus datos se guardan en la nube correctamente.");
        } catch (error: any) {
            alert(`❌ Error de conexión: ${error.message || 'No se pudo contactar con Firestore.'}`);
        } finally {
            setIsSyncing(false);
        }
    };

    const handleConfigSave = (config: FirebaseConfig) => {
        saveFirebaseConfig(config);
        setIsFirebaseConfigModalOpen(false);
        try {
            initFirebase(config);
            handleFirebaseLogin(); 
        } catch (e) {
            alert("Error inicializando Firebase con esa configuración.");
        }
    };

    // --- Generate Temp Data ---
    const handleGenerateTempData = () => {
        const year = new Date().getFullYear();
        const start = new Date(year, 11, 1); // 1 de Diciembre
        const end = new Date(year, 11, 28); 

        setSchedule(prevSchedule => {
            const newSchedule = { ...prevSchedule };
            let loopDate = new Date(start);

            while (loopDate <= end) {
                const wId = getWeekId(loopDate);

                if (!newSchedule[wId]) {
                    const weekDaysForId = getWeekDays(loopDate);
                    newSchedule[wId] = weekDaysForId.map(d => ({
                        date: d,
                        shift: '',
                        status: DayStatus.Work
                    }));
                }

                const dayStr = loopDate.toDateString();
                const dayIndex = newSchedule[wId].findIndex(d => d.date.toDateString() === dayStr);

                if (dayIndex !== -1) {
                    newSchedule[wId][dayIndex] = {
                        ...newSchedule[wId][dayIndex],
                        shift: '10-14 17-21',
                        status: DayStatus.Work
                    };
                }

                loopDate.setDate(loopDate.getDate() + 1);
            }
            return newSchedule;
        });

        setCurrentDate(start);
        alert("Generados turnos del 1 al 28 de Diciembre.");
    };

    // --- Date & Schedule Logic ---

    const weekId = useMemo(() => getWeekId(currentDate), [currentDate]);

    // Original simple mapping without UTC complexity
    const weekDays = useMemo(() => {
        const days = getWeekDays(currentDate);
        if (!schedule[weekId]) {
            return days.map(date => ({ date, shift: '', status: DayStatus.Work }));
        }

        return days.map(date => {
            // Simple date string comparison is robust for local time apps
            const found = schedule[weekId].find(d => d.date.toDateString() === date.toDateString());
            return found ? { ...found, date: date } : { date, shift: '', status: DayStatus.Work };
        });
    }, [currentDate, schedule, weekId]);

    const handleUpdateDay = useCallback((updatedDay: Day) => {
        setSchedule(prevSchedule => {
            // We need to use the weekId corresponding to the updated day, not necessarily the current view's weekId
            const targetWeekId = getWeekId(updatedDay.date);
            const currentWeekData = prevSchedule[targetWeekId] || getWeekDays(updatedDay.date).map(d => ({ date: d, shift: '', status: DayStatus.Work }));

            const newWeekDays = currentWeekData.map(d => {
                if (d.date.toDateString() === updatedDay.date.toDateString()) {
                    return updatedDay;
                }
                return d;
            });
            return { ...prevSchedule, [targetWeekId]: newWeekDays };
        });
        setEditingDay(null);
    }, [schedule]);

    const { totalHours, overtimeHours } = useMemo(() => {
        const workHours = weekDays.reduce((acc, day) => {
            if (day.status === DayStatus.Work) {
                return acc + calculateHoursFromShift(day.shift);
            }
            return acc;
        }, 0);

        const daysOff = weekDays.filter(d => d.status === DayStatus.Holiday || d.status === DayStatus.Vacation).length;
        const extraDaysOff = Math.max(0, daysOff - 2);
        const weeklyTarget = Math.max(0, 40 - (extraDaysOff * 8));
        const overtime = workHours - weeklyTarget;
        return { totalHours: workHours, overtimeHours: overtime };
    }, [weekDays]);

    const handlePrevWeek = () => {
        const newDate = new Date(currentDate);
        newDate.setDate(newDate.getDate() - 7);
        setCurrentDate(newDate);
    };

    const handleNextWeek = () => {
        const newDate = new Date(currentDate);
        newDate.setDate(newDate.getDate() + 7);
        setCurrentDate(newDate);
    };

    const handleDateSelect = (date: Date) => {
        setCurrentDate(date);
        setIsCalendarOpen(false);
    };

    // --- Report Logic ---
    // Recalculates periods by summing weekly results to allow compensation
    const calculatePeriodData = (days: Date[]) => {
        let totalH = 0;
        let totalOvertime = 0;

        // 1. Identify all weeks involved in this period
        const processedWeeks = new Set<string>();
        const relevantDays: Day[] = [];

        days.forEach(date => {
            const wId = getWeekId(date);

            // Get day data
            const weekData = schedule[wId];
            const foundDay = weekData?.find(d => d.date.toDateString() === date.toDateString());
            const dayToUse = foundDay || { date, shift: '', status: DayStatus.Work };
            relevantDays.push(dayToUse);

            if (dayToUse.status === DayStatus.Work) {
                totalH += calculateHoursFromShift(dayToUse.shift);
            }

            // 2. Calculate Overtime PER WEEK (Full week context)
            if (!processedWeeks.has(wId)) {
                processedWeeks.add(wId);

                // Retrieve or generate full week
                const fullWeekDays = weekData || getWeekDays(date).map(d => ({ date: d, shift: '', status: DayStatus.Work }));

                const fullWeekHours = fullWeekDays.reduce((acc, d) => 
                    d.status === DayStatus.Work ? acc + calculateHoursFromShift(d.shift) : acc, 0);

                const daysOff = fullWeekDays.filter(d => d.status === DayStatus.Holiday || d.status === DayStatus.Vacation).length;
                const extraDaysOff = Math.max(0, daysOff - 2);
                const weeklyTarget = Math.max(0, 40 - (extraDaysOff * 8));

                // Allow negative overtime! This is the compensation logic.
                const weekOvertime = fullWeekHours - weeklyTarget;
                totalOvertime += weekOvertime;
            }
        });

        return {
            periodDays: relevantDays.filter(d => d.shift || d.status !== DayStatus.Work),
            totalHours: totalH,
            overtimeHours: totalOvertime
        };
    };

    const handleDownload = async () => {
        setIsDownloading(true);
        try { await downloadScheduleAsPdf({ weekDays, currentDate, totalHours, overtimeHours }); } 
        catch (e) { console.error(e); alert("Error al generar PDF."); } 
        finally { setIsDownloading(false); }
    };

    const handleDownloadMonth = async () => {
        setIsDownloadingMonth(true);
        try {
            const daysInMonth = getDaysInMonth(currentDate);
            const { periodDays, totalHours, overtimeHours } = calculatePeriodData(daysInMonth);

            await downloadMonthScheduleAsPdf({ 
                monthDays: periodDays, 
                currentDate, 
                totalHours, 
                overtimeHours 
            });

        } catch (e) { console.error(e); alert("Error PDF Mensual"); } 
        finally { setIsDownloadingMonth(false); }
    };

    const handleDownloadCustomPeriod = async (startDate: Date, endDate: Date) => {
        setIsDownloadingCustomPeriod(true);
        setIsCustomPeriodModalOpen(false);
        try {
            const periodDates: Date[] = [];
            let loopDate = new Date(startDate);
            while (loopDate <= endDate) {
                periodDates.push(new Date(loopDate));
                loopDate.setDate(loopDate.getDate() + 1);
            }

            const { periodDays, totalHours, overtimeHours } = calculatePeriodData(periodDates);

            await downloadCustomPeriodPdf({ 
                periodDays, 
                startDate, 
                endDate, 
                totalHours, 
                overtimeHours 
            });
        } catch (e) { console.error(e); alert("Error PDF Personalizado"); }
        finally { setIsDownloadingCustomPeriod(false); }
    };

    const handleLogin = () => { setIsAuthenticated(true); };
    const handleLogout = () => { 
        setIsAuthenticated(false); 
        setIsLogoutModalOpen(false); 
        logoutUser(); 
    };

    if (!isAuthenticated) {
        return <Login onLogin={handleLogin} />;
    }

    return (
        <div className="min-h-screen bg-gray-900 text-gray-100 flex flex-col font-sans">
            <Header
                currentWeekTitle={getWeekTitle(currentDate)}
                onPrevWeek={handlePrevWeek}
                onNextWeek={handleNextWeek}
                onCalendarClick={() => setIsCalendarOpen(true)}
                onLogout={() => setIsLogoutModalOpen(true)}
                user={firebaseUser}
                isSyncing={isSyncing}
                onLogin={handleFirebaseLogin}
                onSignOut={handleFirebaseLogout}
                onConfigure={() => setIsFirebaseConfigModalOpen(true)}
                onTestConnection={handleTestConnection}
            />

            <main className="flex-grow py-4 md:py-6 lg:py-8">
                <WeekView 
                    days={weekDays} 
                    onEditDay={setEditingDay} 
                />
            </main>

            <Summary 
                totalHours={totalHours} 
                overtimeHours={overtimeHours}
                onDownload={handleDownload}
                isDownloading={isDownloading}
                onDownloadMonth={handleDownloadMonth}
                isDownloadingMonth={isDownloadingMonth}
                onOpenCustomPeriodModal={() => setIsCustomPeriodModalOpen(true)}
                isDownloadingCustomPeriod={isDownloadingCustomPeriod}
                onGenerateTempData={handleGenerateTempData}
            />

            {editingDay && (
                <EditShiftModal
                    day={editingDay}
                    onClose={() => setEditingDay(null)}
                    onSave={handleUpdateDay}
                    templates={templates}
                    onManageTemplates={() => setIsManagingTemplates(true)}
                />
            )}
            {isManagingTemplates && (
                <ManageTemplatesModal
                    templates={templates}
                    onAddTemplate={addTemplate}
                    onDeleteTemplate={deleteTemplate}
                    onClose={() => setIsManagingTemplates(false)}
                />
            )}
             {isCalendarOpen && (
                <CalendarPickerModal
                    isOpen={isCalendarOpen}
                    onClose={() => setIsCalendarOpen(false)}
                    currentDate={currentDate}
                    onDateSelect={handleDateSelect}
                />
            )}
            {isCustomPeriodModalOpen && (
                <CustomPeriodModal
                    isOpen={isCustomPeriodModalOpen}
                    onClose={() => setIsCustomPeriodModalOpen(false)}
                    onConfirm={handleDownloadCustomPeriod}
                />
            )}
            {isLogoutModalOpen && (
                <ConfirmModal
                    isOpen={isLogoutModalOpen}
                    title="Cerrar Sesión"
                    message="¿Estás seguro de que quieres cerrar la sesión de la aplicación?"
                    onConfirm={handleLogout}
                    onCancel={() => setIsLogoutModalOpen(false)}
                    confirmText="Cerrar Sesión"
                />
            )}
            {isFirebaseConfigModalOpen && (
                <FirebaseConfigModal onSave={handleConfigSave} />
            )}
        </div>
    );
};

export default App;

export interface ShiftPart {
    start: number;
    end: number;
}

const parseTimeToHours = (timeStr: string): number => {
    if (!timeStr) return NaN;
    const trimmed = timeStr.trim().toUpperCase().replace(/,/g, '.');

    if (trimmed === 'C' || trimmed === 'CIERRE') return 24;

    // Handle HH:MM
    if (trimmed.includes(':')) {
        const [h, m] = trimmed.split(':').map(Number);
        if (!isNaN(h) && !isNaN(m)) return h + m / 60;
    }

    // Handle Decimal
    const num = Number(trimmed);
    if (!isNaN(num)) {
        return num;
    }

    return NaN;
};

export const parseShiftParts = (shift: string): ShiftPart[] => {
    if (!shift) return [];

    // Normalize format: replace dashes and trim
    const normalized = shift.replace(/[–—]/g, '-').trim();

    const parts: ShiftPart[] = [];
    const tokens = normalized.split(/\s+/); // Split by one or more spaces

    let i = 0;
    while (i < tokens.length) {
        const token = tokens[i];

        if (token.includes('-')) {
            // Case 1: Range with hyphen (e.g., "20-00", "12-16")
            const [startStr, endStr] = token.split('-');
            if (startStr && endStr) {
                const start = parseTimeToHours(startStr);
                let end = parseTimeToHours(endStr);

                if (!isNaN(start) && !isNaN(end)) {
                    // Handle midnight crossing (20-02 -> 20 to 26)
                    if (end < start) end += 24;
                    // Handle 00 as 24 if it's the end of a shift starting later
                    if (end === 0 && start > 0) end = 24;

                    parts.push({ start, end });
                }
            }
            i++;
        } else {
            // Case 2: Space separated range? (e.g., "13:30 17:30")
            // Check if this token is a time AND the next token is a time (and not a range itself)
            const start = parseTimeToHours(token);

            if (!isNaN(start)) {
                // Peek at next token
                if (i + 1 < tokens.length) {
                    const nextToken = tokens[i+1];
                    // Verify next token is NOT a hyphenated range (e.g. avoid merging "16" with "20-23")
                    if (!nextToken.includes('-')) {
                        const end = parseTimeToHours(nextToken);
                        if (!isNaN(end)) {
                            // We found a pair: "start" "end"
                            let adjustedEnd = end;
                            if (adjustedEnd < start) adjustedEnd += 24;
                            if (adjustedEnd === 0 && start > 0) adjustedEnd = 24;

                            parts.push({ start, end: adjustedEnd });
                            i += 2; // Consume both tokens
                            continue;
                        }
                    }
                }
            }
            // If no pattern matched, move to next token
            i++;
        }
    }

    return parts;
};

export const calculateHoursFromShift = (shift: string): number => {
    const parts = parseShiftParts(shift);
    const total = parts.reduce((acc, part) => acc + (part.end - part.start), 0);
    return Math.round(total * 100) / 100;
};

// Formatter for PDF output
const formatTimeVal = (val: number) => {
    let h = Math.floor(val);
    const m = Math.round((val - h) * 60);
    if (h >= 24) h -= 24;
    return `${h.toString().padStart(2,'0')}:${m.toString().padStart(2,'0')}`;
};

export const formatShift = (shift: string): string => {
    const parts = parseShiftParts(shift);
    if (parts.length === 0) return shift; // Return original if not parseable
    return parts.map(p => `${formatTimeVal(p.start)}-${formatTimeVal(p.end)}`).join(' ');
};

// Helper to get the week number for a date (Local Time implementation)
const getWeekNumber = (d: Date): number => {
    // Copy date so don't modify original
    d = new Date(d.getFullYear(), d.getMonth(), d.getDate());
    // Set to nearest Thursday: current date + 4 - current day number
    // Make Sunday's day number 7
    d.setDate(d.getDate() + 4 - (d.getDay() || 7));
    // Get first day of year
    const yearStart = new Date(d.getFullYear(), 0, 1);
    // Calculate full weeks to nearest Thursday
    const weekNo = Math.ceil((((d.getTime() - yearStart.getTime()) / 86400000) + 1) / 7);
    return weekNo;
}

export const getWeekId = (date: Date): string => {
    // We must use the "Week Year" for the ID, not necessarily the calendar year.
    // E.g. Dec 30 2024 might be Week 1 of 2025.

    // Copy date and move to nearest Thursday to determine the week-year
    const d = new Date(date.getFullYear(), date.getMonth(), date.getDate());
    d.setDate(d.getDate() + 4 - (d.getDay() || 7));
    const year = d.getFullYear(); // This is the correct year for the week ID

    const week = getWeekNumber(date);
    return `${year}-${week.toString().padStart(2, '0')}`;
};

export const getWeekDays = (date: Date): Date[] => {
    const days: Date[] = [];
    const current = new Date(date);

    // Get Monday of the current week
    const day = current.getDay();
    const diff = current.getDate() - day + (day === 0 ? -6 : 1); // adjust when day is sunday

    const monday = new Date(current.setDate(diff));
    monday.setHours(0, 0, 0, 0); // Normalize time

    for (let i = 0; i < 7; i++) {
        const nextDay = new Date(monday);
        nextDay.setDate(monday.getDate() + i);
        days.push(nextDay);
    }
    return days;
};

export const getDaysInMonth = (date: Date): Date[] => {
    const year = date.getFullYear();
    const month = date.getMonth();
    const days: Date[] = [];
    const day = new Date(year, month, 1);

    while (day.getMonth() === month) {
        days.push(new Date(day));
        day.setDate(day.getDate() + 1);
    }
    return days;
};

export const getWeekTitle = (date: Date): string => {
    const weekDays = getWeekDays(date);
    const firstDay = weekDays[0];
    const lastDay = weekDays[6];

    const options: Intl.DateTimeFormatOptions = { month: 'long', day: 'numeric' };

    const firstDayStr = firstDay.toLocaleDateString('es-ES', options);
    const lastDayStr = lastDay.toLocaleDateString('es-ES', options);

    return `Semana del ${firstDayStr} al ${lastDayStr}`;
};

export const getMonthTitle = (date: Date): string => {
    return date.toLocaleDateString('es-ES', { month: 'long', year: 'numeric' });
};

export const formatDayDate = (date: Date): string => {
    return date.toLocaleDateString('es-ES', { day: 'numeric' });
};

export const formatDayName = (date: Date): string => {
    return date.toLocaleDateString('es-ES', { weekday: 'long' });
};

import React, { useState, useMemo, useCallback, useEffect, useRef } from 'react';
import { Day, Schedule, DayStatus, FirebaseUser, FirebaseConfig } from './types';
import { getWeekId, getWeekDays, getWeekTitle, getDaysInMonth } from './utils/dateUtils';
import { calculateHoursFromShift } from './services/scheduleService';
import { downloadScheduleAsPdf, downloadMonthScheduleAsPdf, downloadCustomPeriodPdf } from './services/pdfService';
import Header from './components/Header';
import WeekView from './components/WeekView';
import Summary from './components/Summary';
import EditShiftModal from './components/EditShiftModal';
import { useShiftTemplates } from './hooks/useShiftTemplates';
import CalendarPickerModal from './components/CalendarPickerModal';
import ManageTemplatesModal from './components/ManageTemplatesModal';
import CustomPeriodModal from './components/CustomPeriodModal';
import Login from './components/Login';
import ConfirmModal from './components/ConfirmModal';
import FirebaseConfigModal from './components/FirebaseConfigModal';

import { saveFirebaseConfig, getFirebaseConfig, isFirebaseConfigured } from './services/apiKeyService';
import { initFirebase, loginWithGoogle, logoutUser, subscribeToAuthChanges, subscribeToSchedule, saveScheduleToFirestore, testFirestoreConnection } from './services/firebaseService';
import { useDebouncedCallback } from './hooks/useDebouncedCallback';

const SCHEDULE_STORAGE_KEY = 'bienveAppSchedule';
const AUTH_STORAGE_KEY = 'bienveAppIsAuthenticated';

const App: React.FC = () => {
    // --- Authentication State (App Local) ---
    const [isAuthenticated, setIsAuthenticated] = useState(() => {
        return localStorage.getItem(AUTH_STORAGE_KEY) === 'true';
    });

    // --- Core Data State ---
    const [currentDate, setCurrentDate] = useState(new Date());
    const [schedule, setSchedule] = useState<Schedule>(() => {
        try {
            const savedSchedule = localStorage.getItem(SCHEDULE_STORAGE_KEY);
            if (savedSchedule) {
                const parsed = JSON.parse(savedSchedule);
                Object.keys(parsed).forEach(weekId => {
                    parsed[weekId] = parsed[weekId].map((day: any) => ({
                        ...day,
                        date: new Date(day.date),
                    }));
                });
                return parsed;
            }
        } catch (error) {
            console.error("Failed to load schedule from localStorage", error);
        }
        return {};
    });

    // --- Firebase Integration State ---
    const [firebaseUser, setFirebaseUser] = useState<FirebaseUser | null>(null);
    const [isFirebaseConfigModalOpen, setIsFirebaseConfigModalOpen] = useState(false);
    const [isSyncing, setIsSyncing] = useState(false);
    const isRemoteUpdate = useRef(false);

    // --- UI State ---
    const [editingDay, setEditingDay] = useState<Day | null>(null);
    const { templates, addTemplate, deleteTemplate } = useShiftTemplates();
    const [isManagingTemplates, setIsManagingTemplates] = useState(false);
    const [isDownloading, setIsDownloading] = useState(false);
    const [isDownloadingMonth, setIsDownloadingMonth] = useState(false);
    const [isDownloadingCustomPeriod, setIsDownloadingCustomPeriod] = useState(false);
    const [isCalendarOpen, setIsCalendarOpen] = useState(false);
    const [isCustomPeriodModalOpen, setIsCustomPeriodModalOpen] = useState(false);
    const [isLogoutModalOpen, setIsLogoutModalOpen] = useState(false);

    useEffect(() => {
        localStorage.setItem(AUTH_STORAGE_KEY, String(isAuthenticated));
    }, [isAuthenticated]);

    useEffect(() => {
        try {
            localStorage.setItem(SCHEDULE_STORAGE_KEY, JSON.stringify(schedule));
        } catch (error) {
            console.error("Failed to save schedule to localStorage", error);
        }
    }, [schedule]);

    // --- Firebase Logic ---
    useEffect(() => {
        if (isAuthenticated && isFirebaseConfigured()) {
            const config = getFirebaseConfig();
            if (config) {
                try {
                    initFirebase(config);
                    const unsubscribeAuth = subscribeToAuthChanges((user) => {
                        if (user) {
                            setFirebaseUser({
                                uid: user.uid,
                                displayName: user.displayName,
                                email: user.email,
                                photoURL: user.photoURL
                            });
                        } else {
                            setFirebaseUser(null);
                        }
                    });
                    return () => unsubscribeAuth();
                } catch (e) {
                    console.error("Firebase init failed", e);
                }
            }
        }
    }, [isAuthenticated]);

    useEffect(() => {
        if (firebaseUser?.uid) {
            setIsSyncing(true);
            const unsubscribeSchedule = subscribeToSchedule(firebaseUser.uid, (remoteSchedule) => {
                isRemoteUpdate.current = true;
                setSchedule(remoteSchedule);
                setIsSyncing(false);
                setTimeout(() => { isRemoteUpdate.current = false; }, 100);
            });
            return () => unsubscribeSchedule();
        }
    }, [firebaseUser?.uid]);

    const debouncedSaveToFirestore = useDebouncedCallback(async (currentSchedule: Schedule, uid: string) => {
        if (!uid) return;
        setIsSyncing(true);
        try {
            await saveScheduleToFirestore(uid, currentSchedule);
        } catch (e) {
            console.error("Save to firestore failed", e);
        } finally {
            setIsSyncing(false);
        }
    }, 1000);

    useEffect(() => {
        if (firebaseUser?.uid && !isRemoteUpdate.current) {
            debouncedSaveToFirestore(schedule, firebaseUser.uid);
        }
    }, [schedule, firebaseUser, debouncedSaveToFirestore]);

    // --- Handlers ---

    const handleFirebaseLogin = async () => {
        if (!isFirebaseConfigured()) {
            setIsFirebaseConfigModalOpen(true);
            return;
        }
        try {
            const config = getFirebaseConfig();
            if (config) initFirebase(config);
            await loginWithGoogle();
        } catch (error: any) {
            alert(error.message);
        }
    };

    const handleFirebaseLogout = async () => {
        await logoutUser();
        setFirebaseUser(null);
    };

    const handleTestConnection = async () => {
        if (!firebaseUser?.uid) return;
        setIsSyncing(true);
        try {
            await testFirestoreConnection(firebaseUser.uid);
            alert("✅ Conexión exitosa: Tus datos se guardan en la nube correctamente.");
        } catch (error: any) {
            alert(`❌ Error de conexión: ${error.message || 'No se pudo contactar con Firestore.'}`);
        } finally {
            setIsSyncing(false);
        }
    };

    const handleConfigSave = (config: FirebaseConfig) => {
        saveFirebaseConfig(config);
        setIsFirebaseConfigModalOpen(false);
        try {
            initFirebase(config);
            handleFirebaseLogin(); 
        } catch (e) {
            alert("Error inicializando Firebase con esa configuración.");
        }
    };

    // --- Generate Temp Data ---
    const handleGenerateTempData = () => {
        const year = new Date().getFullYear();
        const start = new Date(year, 11, 1); // 1 de Diciembre
        const end = new Date(year, 11, 28); 

        setSchedule(prevSchedule => {
            const newSchedule = { ...prevSchedule };
            let loopDate = new Date(start);

            while (loopDate <= end) {
                const wId = getWeekId(loopDate);

                if (!newSchedule[wId]) {
                    const weekDaysForId = getWeekDays(loopDate);
                    newSchedule[wId] = weekDaysForId.map(d => ({
                        date: d,
                        shift: '',
                        status: DayStatus.Work
                    }));
                }

                const dayStr = loopDate.toDateString();
                const dayIndex = newSchedule[wId].findIndex(d => d.date.toDateString() === dayStr);

                if (dayIndex !== -1) {
                    newSchedule[wId][dayIndex] = {
                        ...newSchedule[wId][dayIndex],
                        shift: '10-14 17-21',
                        status: DayStatus.Work
                    };
                }

                loopDate.setDate(loopDate.getDate() + 1);
            }
            return newSchedule;
        });

        setCurrentDate(start);
        alert("Generados turnos del 1 al 28 de Diciembre.");
    };

    // --- Date & Schedule Logic ---

    const weekId = useMemo(() => getWeekId(currentDate), [currentDate]);

    // Original simple mapping without UTC complexity
    const weekDays = useMemo(() => {
        const days = getWeekDays(currentDate);
        if (!schedule[weekId]) {
            return days.map(date => ({ date, shift: '', status: DayStatus.Work }));
        }

        return days.map(date => {
            // Simple date string comparison is robust for local time apps
            const found = schedule[weekId].find(d => d.date.toDateString() === date.toDateString());
            return found ? { ...found, date: date } : { date, shift: '', status: DayStatus.Work };
        });
    }, [currentDate, schedule, weekId]);

    const handleUpdateDay = useCallback((updatedDay: Day) => {
        setSchedule(prevSchedule => {
            // 1. Calculate the ID of the week this day belongs to
            const targetWeekId = getWeekId(updatedDay.date);

            // 2. Get existing data for that week OR retrieve empty days
            const existingWeek = prevSchedule[targetWeekId] || [];

            // 3. Generate a fresh 7-day structure for that week to ensure no gaps
            const fullWeekDates = getWeekDays(updatedDay.date);

            const newWeekDays = fullWeekDates.map(date => {
                // If this is the specific day being updated, use the new data
                if (date.toDateString() === updatedDay.date.toDateString()) {
                    return updatedDay;
                }

                // Otherwise, try to find this day in the existing schedule data
                const existingDay = existingWeek.find(d => d.date.toDateString() === date.toDateString());

                // Return preserved data or a default empty day
                return existingDay || { date, shift: '', status: DayStatus.Work };
            });

            return { ...prevSchedule, [targetWeekId]: newWeekDays };
        });
        setEditingDay(null);
    }, []);

    const { totalHours, overtimeHours } = useMemo(() => {
        const workHours = weekDays.reduce((acc, day) => {
            if (day.status === DayStatus.Work) {
                return acc + calculateHoursFromShift(day.shift);
            }
            return acc;
        }, 0);

        const daysOff = weekDays.filter(d => d.status === DayStatus.Holiday || d.status === DayStatus.Vacation).length;
        const extraDaysOff = Math.max(0, daysOff - 2);
        const weeklyTarget = Math.max(0, 40 - (extraDaysOff * 8));
        const overtime = workHours - weeklyTarget;
        return { totalHours: workHours, overtimeHours: overtime };
    }, [weekDays]);

    const handlePrevWeek = () => {
        const newDate = new Date(currentDate);
        newDate.setDate(newDate.getDate() - 7);
        setCurrentDate(newDate);
    };

    const handleNextWeek = () => {
        const newDate = new Date(currentDate);
        newDate.setDate(newDate.getDate() + 7);
        setCurrentDate(newDate);
    };

    const handleDateSelect = (date: Date) => {
        setCurrentDate(date);
        setIsCalendarOpen(false);
    };

    // --- Report Logic ---
    const calculatePeriodData = (days: Date[]) => {
        let totalH = 0;
        let totalOvertime = 0;

        const processedWeeks = new Set<string>();
        const relevantDays: Day[] = [];

        days.forEach(date => {
            const wId = getWeekId(date);

            const weekData = schedule[wId];
            const foundDay = weekData?.find(d => d.date.toDateString() === date.toDateString());
            const dayToUse = foundDay || { date, shift: '', status: DayStatus.Work };
            relevantDays.push(dayToUse);

            if (dayToUse.status === DayStatus.Work) {
                totalH += calculateHoursFromShift(dayToUse.shift);
            }

            if (!processedWeeks.has(wId)) {
                processedWeeks.add(wId);
                const fullWeekDays = weekData || getWeekDays(date).map(d => ({ date: d, shift: '', status: DayStatus.Work }));
                const fullWeekHours = fullWeekDays.reduce((acc, d) => 
                    d.status === DayStatus.Work ? acc + calculateHoursFromShift(d.shift) : acc, 0);

                const daysOff = fullWeekDays.filter(d => d.status === DayStatus.Holiday || d.status === DayStatus.Vacation).length;
                const extraDaysOff = Math.max(0, daysOff - 2);
                const weeklyTarget = Math.max(0, 40 - (extraDaysOff * 8));

                const weekOvertime = fullWeekHours - weeklyTarget;
                totalOvertime += weekOvertime;
            }
        });

        return {
            periodDays: relevantDays.filter(d => d.shift || d.status !== DayStatus.Work),
            totalHours: totalH,
            overtimeHours: totalOvertime
        };
    };

    const handleDownload = async () => {
        setIsDownloading(true);
        try { await downloadScheduleAsPdf({ weekDays, currentDate, totalHours, overtimeHours }); } 
        catch (e) { console.error(e); alert("Error al generar PDF."); } 
        finally { setIsDownloading(false); }
    };

    const handleDownloadMonth = async () => {
        setIsDownloadingMonth(true);
        try {
            const daysInMonth = getDaysInMonth(currentDate);
            const { periodDays, totalHours, overtimeHours } = calculatePeriodData(daysInMonth);

            await downloadMonthScheduleAsPdf({ 
                monthDays: periodDays, 
                currentDate, 
                totalHours, 
                overtimeHours 
            });

        } catch (e) { console.error(e); alert("Error PDF Mensual"); } 
        finally { setIsDownloadingMonth(false); }
    };

    const handleDownloadCustomPeriod = async (startDate: Date, endDate: Date) => {
        setIsDownloadingCustomPeriod(true);
        setIsCustomPeriodModalOpen(false);
        try {
            const periodDates: Date[] = [];
            let loopDate = new Date(startDate);
            while (loopDate <= endDate) {
                periodDates.push(new Date(loopDate));
                loopDate.setDate(loopDate.getDate() + 1);
            }

            const { periodDays, totalHours, overtimeHours } = calculatePeriodData(periodDates);

            await downloadCustomPeriodPdf({ 
                periodDays, 
                startDate, 
                endDate, 
                totalHours, 
                overtimeHours 
            });
        } catch (e) { console.error(e); alert("Error PDF Personalizado"); }
        finally { setIsDownloadingCustomPeriod(false); }
    };

    const handleLogin = () => { setIsAuthenticated(true); };
    const handleLogout = () => { 
        setIsAuthenticated(false); 
        setIsLogoutModalOpen(false); 
        logoutUser(); 
    };

    if (!isAuthenticated) {
        return <Login onLogin={handleLogin} />;
    }

    return (
        <div className="min-h-screen bg-gray-900 text-gray-100 flex flex-col font-sans">
            <Header
                currentWeekTitle={getWeekTitle(currentDate)}
                onPrevWeek={handlePrevWeek}
                onNextWeek={handleNextWeek}
                onCalendarClick={() => setIsCalendarOpen(true)}
                onLogout={() => setIsLogoutModalOpen(true)}
                user={firebaseUser}
                isSyncing={isSyncing}
                onLogin={handleFirebaseLogin}
                onSignOut={handleFirebaseLogout}
                onConfigure={() => setIsFirebaseConfigModalOpen(true)}
                onTestConnection={handleTestConnection}
            />

            <main className="flex-grow py-4 md:py-6 lg:py-8">
                <WeekView 
                    days={weekDays} 
                    onEditDay={setEditingDay} 
                />
            </main>

            <Summary 
                totalHours={totalHours} 
                overtimeHours={overtimeHours}
                onDownload={handleDownload}
                isDownloading={isDownloading}
                onDownloadMonth={handleDownloadMonth}
                isDownloadingMonth={isDownloadingMonth}
                onOpenCustomPeriodModal={() => setIsCustomPeriodModalOpen(true)}
                isDownloadingCustomPeriod={isDownloadingCustomPeriod}
                onGenerateTempData={handleGenerateTempData}
            />

            {editingDay && (
                <EditShiftModal
                    day={editingDay}
                    onClose={() => setEditingDay(null)}
                    onSave={handleUpdateDay}
                    templates={templates}
                    onManageTemplates={() => setIsManagingTemplates(true)}
                />
            )}
            {isManagingTemplates && (
                <ManageTemplatesModal
                    templates={templates}
                    onAddTemplate={addTemplate}
                    onDeleteTemplate={deleteTemplate}
                    onClose={() => setIsManagingTemplates(false)}
                />
            )}
             {isCalendarOpen && (
                <CalendarPickerModal
                    isOpen={isCalendarOpen}
                    onClose={() => setIsCalendarOpen(false)}
                    currentDate={currentDate}
                    onDateSelect={handleDateSelect}
                />
            )}
            {isCustomPeriodModalOpen && (
                <CustomPeriodModal
                    isOpen={isCustomPeriodModalOpen}
                    onClose={() => setIsCustomPeriodModalOpen(false)}
                    onConfirm={handleDownloadCustomPeriod}
                />
            )}
            {isLogoutModalOpen && (
                <ConfirmModal
                    isOpen={isLogoutModalOpen}
                    title="Cerrar Sesión"
                    message="¿Estás seguro de que quieres cerrar la sesión de la aplicación?"
                    onConfirm={handleLogout}
                    onCancel={() => setIsLogoutModalOpen(false)}
                    confirmText="Cerrar Sesión"
                />
            )}
            {isFirebaseConfigModalOpen && (
                <FirebaseConfigModal onSave={handleConfigSave} />
            )}
        </div>
    );
};

export default App;
